export default "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#F4F8FD\">\n<meta name=\"description\" content=\"PharmaCheck — prescription scanning, inventory and profit reporting for pharmacy teams.\">\n<title>PharmaCheck</title>\n<link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect width='32' height='32' rx='8' fill='%231A73E8'/><path d='M10 9h8a5 5 0 0 1 0 10h-4v5h-4z' fill='white'/></svg>\">\n<style>\n/* =====================================================================\n   PharmaCheck — pharmacy management UI\n   Light-blue / white theme, iOS-style phone shell.\n   ===================================================================== */\n\n:root {\n  /* Brand blues */\n  --blue-50:  #F2F7FE;\n  --blue-100: #E4EFFC;\n  --blue-200: #C9E0FA;\n  --blue-300: #9CC7F5;\n  --blue-500: #2B84EF;\n  --blue-600: #1A73E8;\n  --blue-700: #1360C9;\n\n  /* Neutrals */\n  --bg:       #EEF4FB;\n  --surface:  #FFFFFF;\n  --ink:      #0E1B2A;\n  --ink-2:    #37485C;\n  --muted:    #7A8CA1;\n  --line:     #E4EDF7;\n\n  /* Semantic */\n  --green:    #0FA45C;\n  --green-2:  #0C8A4D;\n  --green-bg: #E4F7ED;\n  --red:      #E03B45;\n  --red-bg:   #FDEBEC;\n  --amber:    #E08A00;\n  --amber-bg: #FDF2DF;\n  --violet:   #6C5CE7;\n  --teal:     #0FA3A3;\n\n  /* Elevation */\n  --sh-sm: 0 1px 2px rgba(14, 40, 74, .05), 0 3px 10px rgba(14, 40, 74, .05);\n  --sh-md: 0 2px 6px rgba(14, 40, 74, .06), 0 12px 28px rgba(14, 40, 74, .09);\n  --sh-lg: 0 18px 50px rgba(14, 40, 74, .22);\n\n  --r-sm: 12px;\n  --r-md: 18px;\n  --r-lg: 24px;\n\n  --tab-h: 78px;\n\n  --font: -apple-system, BlinkMacSystemFont, \"SF Pro Text\", \"Segoe UI\",\n          Inter, Roboto, \"Helvetica Neue\", Arial, sans-serif;\n}\n\n* { box-sizing: border-box; }\n\n/* Component display rules outrank the UA [hidden] rule; this restores it. */\n[hidden] { display: none !important; }\n\nhtml, body {\n  margin: 0;\n  padding: 0;\n  height: 100%;\n}\n\nbody {\n  font-family: var(--font);\n  color: var(--ink);\n  background:\n    radial-gradient(1100px 700px at 15% -10%, #DCEBFC 0%, transparent 60%),\n    radial-gradient(900px 600px at 100% 110%, #E7F2FF 0%, transparent 55%),\n    #DFE9F5;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n.sprite { display: none; }\n\n.icon {\n  width: 22px;\n  height: 22px;\n  fill: none;\n  stroke: currentColor;\n  stroke-width: 1.8;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n  flex: none;\n}\n.icon--xs { width: 14px; height: 14px; stroke-width: 2.1; }\n\nbutton { font: inherit; color: inherit; }\n\n/* ---------------------------------------------------------------- shell */\n.stage {\n  min-height: 100%;\n  display: grid;\n  place-items: center;\n  padding: 28px 16px;\n}\n\n.phone {\n  position: relative;\n  width: 390px;\n  height: 844px;\n  max-height: calc(100vh - 56px);\n  background: var(--bg);\n  border-radius: 46px;\n  border: 11px solid #0B1524;\n  box-shadow: var(--sh-lg), 0 0 0 2px #2A3646 inset;\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n  isolation: isolate;\n}\n\n/* --------------------------------------------------------- status bar */\n.statusbar {\n  flex: none;\n  height: 50px;\n  padding: 14px 26px 0;\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  font-size: 15px;\n  font-weight: 650;\n  letter-spacing: .2px;\n  color: var(--ink);\n  position: relative;\n  z-index: 6;\n}\n.statusbar__notch {\n  position: absolute;\n  left: 50%;\n  top: 0;\n  transform: translateX(-50%);\n  width: 122px;\n  height: 30px;\n  background: #0B1524;\n  border-radius: 0 0 18px 18px;\n}\n.statusbar__icons { display: flex; align-items: center; gap: 6px; }\n.statusbar__icons svg { height: 11px; fill: currentColor; }\n.sb-signal { width: 18px; }\n.sb-wifi   { width: 16px; }\n.sb-batt   { width: 25px; }\n\n/* The scanner runs edge to edge, so the shell behind the status bar\n   goes dark with it. */\n.phone.is-dark { background: #0A1420; }\n.phone.is-dark .statusbar { color: #fff; }\n\n/* ------------------------------------------------------------ viewport */\n.viewport {\n  position: relative;\n  flex: 1;\n  min-height: 0;\n}\n\n.screen {\n  position: absolute;\n  inset: 0;\n  display: none;\n  flex-direction: column;\n}\n.screen.is-active {\n  display: flex;\n  animation: screen-in .28s cubic-bezier(.22, .8, .3, 1);\n}\n@keyframes screen-in {\n  from { opacity: 0; transform: translateY(10px) scale(.995); }\n  to   { opacity: 1; transform: none; }\n}\n\n.screen--scroll {\n  overflow-y: auto;\n  overflow-x: hidden;\n  -webkit-overflow-scrolling: touch;\n  padding: 4px 20px 28px;\n  scrollbar-width: none;\n}\n.screen--scroll::-webkit-scrollbar { display: none; }\n\n/* A screen whose header stays put while an inner region scrolls. Lets the\n   floating action button sit still instead of scrolling with the list. */\n.screen--fixed {\n  overflow: hidden;\n  padding: 4px 20px 0;\n}\n.scrollarea {\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  -webkit-overflow-scrolling: touch;\n  margin: 0 -20px;\n  padding: 2px 20px 24px;\n  scrollbar-width: none;\n}\n.scrollarea::-webkit-scrollbar { display: none; }\n\n/* -------------------------------------------------------------- header */\n.apphead {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 12px 0 18px;\n}\n.apphead--compact { align-items: center; padding-bottom: 14px; }\n.apphead--compact > div { flex: 1; }\n\n.apphead__date {\n  margin: 0 0 4px;\n  font-size: 12.5px;\n  font-weight: 600;\n  letter-spacing: .5px;\n  text-transform: uppercase;\n  color: var(--blue-600);\n}\n.apphead__title {\n  margin: 0;\n  font-size: 27px;\n  line-height: 1.15;\n  font-weight: 750;\n  letter-spacing: -.6px;\n}\n.apphead__title--sm { font-size: 23px; letter-spacing: -.4px; }\n.apphead__sub {\n  margin: 5px 0 0;\n  font-size: 13px;\n  color: var(--muted);\n}\n.apphead__actions { display: flex; align-items: center; gap: 10px; }\n\n.avatar {\n  width: 42px;\n  height: 42px;\n  border-radius: 50%;\n  display: grid;\n  place-items: center;\n  font-size: 14px;\n  font-weight: 700;\n  color: #fff;\n  background: linear-gradient(150deg, var(--blue-500), var(--blue-700));\n  box-shadow: 0 4px 12px rgba(26, 115, 232, .35);\n}\n\n/* ------------------------------------------------------------- buttons */\n.iconbtn {\n  position: relative;\n  width: 42px;\n  height: 42px;\n  border-radius: 14px;\n  border: 0;\n  display: grid;\n  place-items: center;\n  cursor: pointer;\n  background: transparent;\n  transition: transform .12s ease, background .18s ease;\n}\n.iconbtn:active { transform: scale(.92); }\n.iconbtn--ghost {\n  background: var(--surface);\n  color: var(--ink-2);\n  box-shadow: var(--sh-sm);\n}\n.iconbtn--glass {\n  background: rgba(255, 255, 255, .16);\n  color: #fff;\n  backdrop-filter: blur(14px);\n  -webkit-backdrop-filter: blur(14px);\n  border-radius: 50%;\n}\n.iconbtn--glass[aria-pressed=\"true\"] {\n  background: #FFD166;\n  color: #4A3200;\n}\n.dot-badge {\n  position: absolute;\n  top: 9px; right: 10px;\n  width: 8px; height: 8px;\n  border-radius: 50%;\n  background: var(--red);\n  box-shadow: 0 0 0 2px var(--surface);\n}\n\n.btn {\n  border: 0;\n  border-radius: 14px;\n  padding: 13px 18px;\n  font-size: 15px;\n  font-weight: 650;\n  cursor: pointer;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  transition: transform .12s ease, box-shadow .18s ease, background .18s ease;\n}\n.btn:active { transform: scale(.975); }\n.btn--primary {\n  background: linear-gradient(160deg, var(--blue-500), var(--blue-700));\n  color: #fff;\n  box-shadow: 0 6px 18px rgba(26, 115, 232, .32);\n}\n.btn--ghost {\n  background: var(--blue-50);\n  color: var(--blue-700);\n}\n.btn--soft {\n  background: var(--blue-100);\n  color: var(--blue-700);\n  border-radius: 12px;\n  padding: 11px 16px;\n  font-size: 14px;\n}\n.btn--block { width: 100%; }\n.btn--lg { padding: 17px 20px; font-size: 16.5px; border-radius: 16px; }\n\n.linkbtn {\n  border: 0;\n  background: none;\n  color: var(--blue-600);\n  font-size: 13.5px;\n  font-weight: 650;\n  display: inline-flex;\n  align-items: center;\n  gap: 3px;\n  cursor: pointer;\n  padding: 4px;\n}\n\n/* --------------------------------------------------------------- cards */\n.card {\n  background: var(--surface);\n  border-radius: var(--r-md);\n  box-shadow: var(--sh-sm);\n}\n\n.section-head {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  margin: 24px 0 12px;\n}\n.section-head--tight { margin: 0 0 14px; }\n.section-title {\n  margin: 0;\n  font-size: 17px;\n  font-weight: 700;\n  letter-spacing: -.25px;\n}\n.section-title--sm { font-size: 15.5px; }\n.section-note {\n  font-size: 11.5px;\n  font-weight: 600;\n  letter-spacing: .5px;\n  text-transform: uppercase;\n  color: var(--muted);\n}\n\n.badge {\n  font-size: 11.5px;\n  font-weight: 700;\n  padding: 5px 10px;\n  border-radius: 999px;\n  white-space: nowrap;\n}\n.badge--green { background: var(--green-bg); color: var(--green-2); }\n.badge--amber { background: var(--amber-bg); color: var(--amber); }\n.badge--red   { background: var(--red-bg);   color: var(--red); }\n.badge--blue  { background: var(--blue-100); color: var(--blue-700); }\n\n/* ============================ 1. DASHBOARD ============================ */\n.quickgrid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 12px;\n}\n.quicktile {\n  aspect-ratio: 1 / 1.06;\n  border: 0;\n  border-radius: 20px;\n  background: var(--surface);\n  box-shadow: var(--sh-sm);\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  padding: 10px 6px;\n  cursor: pointer;\n  transition: transform .14s ease, box-shadow .2s ease;\n}\n.quicktile:active { transform: scale(.955); box-shadow: var(--sh-md); }\n.quicktile__icon {\n  width: 46px;\n  height: 46px;\n  border-radius: 15px;\n  display: grid;\n  place-items: center;\n  color: #fff;\n}\n.quicktile__icon .icon { width: 24px; height: 24px; }\n.quicktile__icon--blue   { background: linear-gradient(155deg, #4A9BF7, var(--blue-700)); box-shadow: 0 6px 14px rgba(26,115,232,.30); }\n.quicktile__icon--teal   { background: linear-gradient(155deg, #2FC5B8, var(--teal));     box-shadow: 0 6px 14px rgba(15,163,163,.28); }\n.quicktile__icon--violet { background: linear-gradient(155deg, #8E82F0, var(--violet));   box-shadow: 0 6px 14px rgba(108,92,231,.28); }\n.quicktile__label {\n  font-size: 12.5px;\n  font-weight: 650;\n  line-height: 1.25;\n  text-align: center;\n  color: var(--ink-2);\n}\n\n.metricgrid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 12px;\n}\n.metric { padding: 15px 15px 14px; }\n.metric__label {\n  margin: 0;\n  font-size: 12.5px;\n  font-weight: 600;\n  color: var(--muted);\n}\n.metric__value {\n  margin: 7px 0 6px;\n  font-size: 29px;\n  font-weight: 750;\n  letter-spacing: -1px;\n  line-height: 1;\n}\n.metric__value--alert { color: var(--red); }\n.metric__delta {\n  margin: 0;\n  font-size: 11.5px;\n  font-weight: 600;\n  color: var(--muted);\n  display: flex;\n  align-items: center;\n  gap: 4px;\n}\n.metric__delta--up   { color: var(--green-2); }\n.metric__delta--down { color: var(--red); }\n\n.activity { list-style: none; margin: 0; padding: 4px 16px; }\n.activity__row {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 13px 0;\n  border-bottom: 1px solid var(--line);\n}\n.activity__row:last-child { border-bottom: 0; }\n.activity__icon {\n  width: 38px; height: 38px;\n  border-radius: 12px;\n  display: grid;\n  place-items: center;\n  background: var(--blue-50);\n  color: var(--blue-600);\n}\n.activity__icon .icon { width: 20px; height: 20px; }\n.activity__body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }\n.activity__name {\n  font-size: 14.5px;\n  font-weight: 650;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.activity__meta { font-size: 12px; color: var(--muted); }\n\n/* ============================= 2. SCANNER ============================= */\n.screen--camera { padding: 0; }\n\n.camera {\n  position: absolute;\n  inset: 0;\n  overflow: hidden;\n  background: #0A1420;\n}\n.camera__feed {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  opacity: 0;\n  transition: opacity .4s ease;\n}\n.camera.is-live .camera__feed { opacity: 1; }\n.camera.is-live .camera__mock { opacity: 0; }\n\n.camera__mock {\n  position: absolute;\n  inset: 0;\n  transition: opacity .4s ease;\n}\n.scene {\n  position: absolute;\n  inset: 0;\n  background:\n    radial-gradient(120% 80% at 50% 35%, #5D6472 0%, #2B3240 55%, #161C27 100%);\n  display: grid;\n  place-items: center;\n}\n.paper {\n  width: 66%;\n  margin-top: -30px;\n  padding: 18px 18px 22px;\n  background: linear-gradient(170deg, #FCFBF7, #ECE9E0);\n  border-radius: 6px;\n  box-shadow: 0 26px 50px rgba(0, 0, 0, .55);\n  transform: perspective(900px) rotateX(7deg) rotate(-1.4deg);\n  font-family: var(--font);\n}\n.paper__head { display: flex; justify-content: space-between; align-items: flex-start; }\n.paper__clinic {\n  margin: 0 0 5px;\n  font-size: 9.5px;\n  font-weight: 750;\n  letter-spacing: 1.1px;\n  color: #4A4437;\n}\n.paper__rx {\n  font-size: 24px;\n  font-weight: 700;\n  color: #6E6353;\n  line-height: 1;\n}\n.paper__rule { height: 1px; background: #CFC8B8; margin: 10px 0 12px; }\n.paper__line {\n  height: 6px;\n  margin: 0 0 9px;\n  border-radius: 3px;\n  background: #CFC8B8;\n  width: 70%;\n}\n.paper__line--sm { height: 4px; background: #D9D3C5; font-size: 0; }\n.paper__qr {\n  width: 104px;\n  height: 104px;\n  margin: 14px auto 14px;\n  background: #fff;\n  padding: 5px;\n  border-radius: 4px;\n  box-shadow: 0 1px 4px rgba(0, 0, 0, .18);\n}\n.paper__qr svg { display: block; width: 100%; height: 100%; }\n\n.camera__vignette {\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n  background:\n    linear-gradient(#0A1420 0%, rgba(10, 20, 32, 0) 22%),\n    linear-gradient(0deg, #0A1420 0%, rgba(10, 20, 32, 0) 30%);\n  opacity: .92;\n}\n\n.flash-burst {\n  position: absolute;\n  inset: 0;\n  background: radial-gradient(60% 45% at 50% 42%, rgba(255, 246, 214, .55), transparent 70%);\n  opacity: 0;\n  pointer-events: none;\n  transition: opacity .3s ease;\n}\n.camera.is-flash .flash-burst { opacity: 1; }\n\n.camtop {\n  position: absolute;\n  top: 12px;\n  left: 16px;\n  right: 16px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n  z-index: 3;\n}\n.camtop__title {\n  text-align: center;\n  color: #fff;\n  font-size: 15.5px;\n  font-weight: 650;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n.camtop__title small {\n  font-size: 10.5px;\n  font-weight: 600;\n  letter-spacing: .4px;\n  text-transform: uppercase;\n  color: rgba(255, 255, 255, .62);\n}\n\n/* Viewfinder */\n.finder {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -58%);\n  width: 246px;\n  height: 246px;\n  border-radius: 26px;\n  z-index: 3;\n  box-shadow:\n    0 0 0 1px rgba(74, 240, 158, .35) inset,\n    0 0 26px rgba(43, 226, 138, .35),\n    0 0 0 2000px rgba(6, 14, 24, .46);\n  transition: box-shadow .35s ease, transform .35s ease;\n}\n.finder__corner {\n  position: absolute;\n  width: 40px;\n  height: 40px;\n  border: 4px solid #3BE58C;\n  filter: drop-shadow(0 0 7px rgba(59, 229, 140, .85));\n  transition: border-color .3s ease;\n}\n.finder__corner--tl { top: -2px; left: -2px;  border-right: 0; border-bottom: 0; border-radius: 26px 0 0 0; }\n.finder__corner--tr { top: -2px; right: -2px; border-left: 0;  border-bottom: 0; border-radius: 0 26px 0 0; }\n.finder__corner--bl { bottom: -2px; left: -2px;  border-right: 0; border-top: 0; border-radius: 0 0 0 26px; }\n.finder__corner--br { bottom: -2px; right: -2px; border-left: 0;  border-top: 0; border-radius: 0 0 26px 0; }\n\n.finder__beam {\n  position: absolute;\n  left: 10px;\n  right: 10px;\n  height: 3px;\n  border-radius: 3px;\n  background: linear-gradient(90deg, transparent, #6BFFB4, transparent);\n  box-shadow: 0 0 16px 3px rgba(59, 229, 140, .7);\n  animation: beam 2.4s cubic-bezier(.55, 0, .45, 1) infinite;\n}\n@keyframes beam {\n  0%, 100% { top: 16px;  opacity: .25; }\n  50%      { top: 224px; opacity: 1; }\n}\n\n.finder__success {\n  position: absolute;\n  inset: 0;\n  display: grid;\n  place-items: center;\n  opacity: 0;\n  pointer-events: none;\n  transition: opacity .25s ease;\n}\n.finder__check {\n  width: 74px;\n  height: 74px;\n  border-radius: 50%;\n  display: grid;\n  place-items: center;\n  color: #fff;\n  background: var(--green);\n  box-shadow: 0 0 0 10px rgba(15, 164, 92, .28), 0 10px 26px rgba(0, 0, 0, .35);\n  transform: scale(.4);\n  transition: transform .38s cubic-bezier(.2, 1.5, .4, 1);\n}\n.finder__check .icon { width: 36px; height: 36px; stroke-width: 2.6; }\n\n.camera.is-locked .finder {\n  box-shadow:\n    0 0 0 3px #3BE58C inset,\n    0 0 40px rgba(59, 229, 140, .7),\n    0 0 0 2000px rgba(6, 14, 24, .62);\n  transform: translate(-50%, -58%) scale(.97);\n}\n.camera.is-locked .finder__beam { display: none; }\n.camera.is-locked .finder__success { opacity: 1; }\n.camera.is-locked .finder__check { transform: scale(1); }\n\n.camera__hint {\n  position: absolute;\n  top: calc(50% + 124px);\n  left: 0;\n  right: 0;\n  margin: 0;\n  padding: 0 40px;\n  text-align: center;\n  color: rgba(255, 255, 255, .92);\n  font-size: 14px;\n  font-weight: 600;\n  letter-spacing: .1px;\n  text-shadow: 0 1px 8px rgba(0, 0, 0, .6);\n  z-index: 3;\n  transition: color .3s ease;\n}\n.camera.is-locked .camera__hint { color: #6BFFB4; }\n\n.camctl {\n  position: absolute;\n  left: 0;\n  right: 0;\n  bottom: 34px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 44px;\n  z-index: 3;\n  transition: opacity .25s ease, transform .25s ease;\n}\n.camera.is-locked .camctl { opacity: 0; transform: translateY(20px); pointer-events: none; }\n\n.shutter {\n  position: relative;\n  width: 74px;\n  height: 74px;\n  border: 0;\n  border-radius: 50%;\n  background: none;\n  cursor: pointer;\n  display: grid;\n  place-items: center;\n}\n.shutter__ring {\n  position: absolute;\n  inset: 0;\n  border-radius: 50%;\n  border: 3px solid rgba(255, 255, 255, .9);\n}\n.shutter__core {\n  width: 58px;\n  height: 58px;\n  border-radius: 50%;\n  background: #fff;\n  transition: transform .12s ease, background .12s ease;\n}\n.shutter:active .shutter__core { transform: scale(.86); background: #D9E6F5; }\n\n/* --------------------------------------------------------------- sheet */\n.sheet {\n  position: absolute;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  z-index: 8;\n  background: var(--surface);\n  border-radius: 26px 26px 0 0;\n  padding: 10px 20px 24px;\n  box-shadow: 0 -12px 40px rgba(8, 22, 40, .28);\n  transform: translateY(102%);\n  transition: transform .38s cubic-bezier(.22, .85, .3, 1);\n}\n.sheet.is-open { transform: none; }\n\n/* The add-stock sheet is anchored to the phone rather than the viewport,\n   so it needs to clear the home indicator. */\n.sheet--modal {\n  padding-bottom: 36px;\n  z-index: 12;\n}\n.sheet__grab {\n  width: 40px;\n  height: 4px;\n  border-radius: 4px;\n  background: #D5DEEA;\n  margin: 2px auto 14px;\n}\n.sheet__title { margin: 0 0 16px; font-size: 19px; font-weight: 720; letter-spacing: -.3px; }\n.sheet__head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n  margin-bottom: 14px;\n}\n.sheet__badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  font-size: 12px;\n  font-weight: 700;\n  color: var(--green-2);\n  background: var(--green-bg);\n  padding: 6px 11px;\n  border-radius: 999px;\n}\n.sheet__code {\n  font-size: 13px;\n  font-weight: 700;\n  letter-spacing: .6px;\n  color: var(--muted);\n  font-variant-numeric: tabular-nums;\n}\n.sheet__actions { display: flex; gap: 10px; margin-top: 18px; }\n.sheet__actions .btn { flex: 1; }\n\n.kv { margin: 0; }\n.kv__row {\n  display: flex;\n  justify-content: space-between;\n  gap: 16px;\n  padding: 9px 0;\n  border-bottom: 1px solid var(--line);\n}\n.kv__row:last-child { border-bottom: 0; }\n.kv dt { font-size: 13px; color: var(--muted); font-weight: 600; }\n.kv dd {\n  margin: 0;\n  font-size: 13.5px;\n  font-weight: 650;\n  text-align: right;\n}\n\n.scrim {\n  position: absolute;\n  inset: 0;\n  background: rgba(9, 22, 40, .42);\n  backdrop-filter: blur(2px);\n  z-index: 11;\n  opacity: 0;\n  transition: opacity .3s ease;\n}\n.scrim.is-on { opacity: 1; }\n\n/* ========================== 3. MANUAL ENTRY ========================== */\n.form { padding: 18px 16px 20px; display: flex; flex-direction: column; gap: 16px; }\n\n.field { display: flex; flex-direction: column; gap: 7px; min-width: 0; }\n.field__label {\n  font-size: 12.5px;\n  font-weight: 650;\n  color: var(--ink-2);\n  letter-spacing: .1px;\n}\n.field__control {\n  position: relative;\n  display: flex;\n  align-items: center;\n  background: var(--blue-50);\n  border: 1.5px solid transparent;\n  border-radius: 13px;\n  transition: border-color .18s ease, background .18s ease, box-shadow .18s ease;\n}\n.field__control:focus-within {\n  background: var(--surface);\n  border-color: var(--blue-500);\n  box-shadow: 0 0 0 4px rgba(43, 132, 239, .13);\n}\n.field__icon {\n  position: absolute;\n  left: 12px;\n  width: 18px;\n  height: 18px;\n  color: var(--blue-500);\n  pointer-events: none;\n}\n.field__control input {\n  width: 100%;\n  border: 0;\n  background: none;\n  outline: none;\n  padding: 14px 14px 14px 40px;\n  font: inherit;\n  font-size: 15px;\n  font-weight: 550;\n  color: var(--ink);\n  border-radius: 13px;\n  min-width: 0;\n}\n.field__control input::placeholder { color: #A9B7C7; font-weight: 500; }\n.field__control input[type=\"number\"]::-webkit-outer-spin-button,\n.field__control input[type=\"number\"]::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }\n.field__control input[type=\"number\"] { -moz-appearance: textfield; }\n\n.field.is-bad .field__control { background: var(--red-bg); border-color: var(--red); }\n.field.is-bad .field__icon { color: var(--red); }\n.field__error {\n  margin: 0;\n  font-size: 11.5px;\n  font-weight: 600;\n  color: var(--red);\n  display: none;\n}\n.field.is-bad .field__error { display: block; }\n\n.field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n\n.hintnote {\n  display: flex;\n  gap: 9px;\n  align-items: flex-start;\n  margin: 16px 2px 0;\n  font-size: 12.5px;\n  line-height: 1.55;\n  color: var(--muted);\n}\n.hintnote .icon { color: var(--blue-500); margin-top: 2px; }\n\n/* The add-stock sheet reuses .field without the .form wrapper's gap. */\n#stock-form { display: flex; flex-direction: column; gap: 14px; }\n\n.qrcard {\n  margin-top: 16px;\n  padding: 18px 16px 20px;\n  text-align: center;\n  animation: screen-in .3s ease;\n}\n.qrcard__head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  text-align: left;\n  margin-bottom: 16px;\n}\n.qrcard__label { margin: 0 0 3px; font-size: 12px; font-weight: 600; color: var(--muted); }\n.qrcard__code {\n  margin: 0;\n  font-size: 19px;\n  font-weight: 750;\n  letter-spacing: .6px;\n  font-variant-numeric: tabular-nums;\n}\n.qrcard__frame {\n  width: 196px;\n  height: 196px;\n  margin: 0 auto;\n  padding: 12px;\n  background: #fff;\n  border: 1.5px solid var(--line);\n  border-radius: var(--r-sm);\n}\n.qrcard__frame svg { display: block; width: 100%; height: 100%; }\n.qrcard__meta {\n  margin: 12px 0 0;\n  white-space: pre-line;\n  font-size: 12px;\n  color: var(--muted);\n  line-height: 1.5;\n}\n.qrcard__tools { margin-top: 14px; }\n\n/* =========================== 4. INVENTORY =========================== */\n.searchbar {\n  position: relative;\n  display: flex;\n  align-items: center;\n  background: var(--surface);\n  border-radius: 14px;\n  box-shadow: var(--sh-sm);\n  margin-bottom: 14px;\n}\n.searchbar__icon {\n  position: absolute;\n  left: 14px;\n  width: 19px;\n  height: 19px;\n  color: var(--muted);\n  pointer-events: none;\n}\n.searchbar input {\n  width: 100%;\n  border: 0;\n  outline: none;\n  background: none;\n  font: inherit;\n  font-size: 15px;\n  padding: 14px 14px 14px 43px;\n  border-radius: 14px;\n  color: var(--ink);\n}\n.searchbar input::placeholder { color: #A2B1C2; }\n.searchbar input::-webkit-search-cancel-button { -webkit-appearance: none; }\n\n.chips { display: flex; gap: 8px; margin-bottom: 14px; flex-wrap: wrap; }\n.chip {\n  border: 1.5px solid var(--line);\n  background: var(--surface);\n  color: var(--ink-2);\n  border-radius: 999px;\n  padding: 8px 14px;\n  font-size: 13px;\n  font-weight: 620;\n  cursor: pointer;\n  transition: all .18s ease;\n}\n.chip.is-on {\n  background: var(--blue-600);\n  border-color: var(--blue-600);\n  color: #fff;\n  box-shadow: 0 4px 12px rgba(26, 115, 232, .28);\n}\n\n.stocklist { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }\n.stockrow {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  background: var(--surface);\n  border-radius: var(--r-md);\n  box-shadow: var(--sh-sm);\n  padding: 14px 15px;\n  animation: screen-in .25s ease;\n}\n.stockrow__dot {\n  width: 11px;\n  height: 11px;\n  border-radius: 50%;\n  flex: none;\n  margin-top: 2px;\n  align-self: flex-start;\n}\n.stockrow--ok  .stockrow__dot { background: var(--green); box-shadow: 0 0 0 4px rgba(15, 164, 92, .16); }\n.stockrow--low .stockrow__dot { background: var(--red);   box-shadow: 0 0 0 4px rgba(224, 59, 69, .16); }\n.stockrow__body { flex: 1; min-width: 0; }\n.stockrow__name {\n  margin: 0 0 4px;\n  font-size: 15px;\n  font-weight: 680;\n  letter-spacing: -.15px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.stockrow__meta {\n  margin: 0;\n  font-size: 11.5px;\n  color: var(--muted);\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  flex-wrap: wrap;\n}\n.stockrow__warn {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  color: var(--red);\n  font-weight: 700;\n}\n.stockrow__right { text-align: right; flex: none; }\n.stockrow__qty {\n  margin: 0;\n  font-size: 19px;\n  font-weight: 750;\n  letter-spacing: -.5px;\n  font-variant-numeric: tabular-nums;\n}\n.stockrow--low .stockrow__qty { color: var(--red); }\n.stockrow__unit { margin: 1px 0 0; font-size: 11px; color: var(--muted); font-weight: 600; }\n\n.emptystate {\n  text-align: center;\n  color: var(--muted);\n  font-size: 14px;\n  padding: 40px 20px;\n}\n\n.fab {\n  position: absolute;\n  right: 20px;\n  bottom: 20px;\n  width: 58px;\n  height: 58px;\n  border: 0;\n  border-radius: 20px;\n  background: linear-gradient(155deg, var(--blue-500), var(--blue-700));\n  color: #fff;\n  display: grid;\n  place-items: center;\n  cursor: pointer;\n  box-shadow: 0 10px 24px rgba(26, 115, 232, .42);\n  z-index: 5;\n  transition: transform .14s ease;\n}\n.fab:active { transform: scale(.92); }\n.fab .icon { width: 26px; height: 26px; stroke-width: 2.4; }\n\n/* ============================ 5. REPORTS ============================ */\n.segmented {\n  position: relative;\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  background: var(--blue-100);\n  border-radius: 14px;\n  padding: 4px;\n  margin-bottom: 18px;\n}\n.segmented__btn {\n  position: relative;\n  z-index: 2;\n  border: 0;\n  background: none;\n  padding: 10px 4px;\n  font-size: 14px;\n  font-weight: 650;\n  color: var(--blue-700);\n  border-radius: 11px;\n  cursor: pointer;\n  transition: color .2s ease;\n}\n.segmented__btn.is-on { color: var(--ink); }\n.segmented__pill {\n  position: absolute;\n  z-index: 1;\n  top: 4px;\n  bottom: 4px;\n  border-radius: 11px;\n  background: var(--surface);\n  box-shadow: var(--sh-sm);\n  transition: transform .3s cubic-bezier(.3, .9, .3, 1), width .3s ease;\n}\n\n.profit {\n  padding: 20px 18px;\n  background:\n    linear-gradient(160deg, #F0FCF5 0%, var(--surface) 55%);\n  border: 1px solid #DDF2E6;\n}\n.profit__label {\n  margin: 0;\n  font-size: 12.5px;\n  font-weight: 650;\n  letter-spacing: .3px;\n  text-transform: uppercase;\n  color: var(--muted);\n}\n.profit__value {\n  margin: 10px 0 8px;\n  font-size: 42px;\n  line-height: 1;\n  font-weight: 780;\n  letter-spacing: -1.8px;\n  color: var(--green-2);\n  font-variant-numeric: tabular-nums;\n}\n.profit__trend {\n  margin: 0;\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 13px;\n  font-weight: 700;\n  color: var(--green-2);\n  background: var(--green-bg);\n  padding: 6px 11px;\n  border-radius: 999px;\n}\n.profit__note { margin: 12px 0 0; font-size: 12px; color: var(--muted); }\n\n.duo { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 12px; }\n.duo__card { padding: 15px; }\n.duo__label { margin: 0; font-size: 12.5px; font-weight: 600; color: var(--muted); }\n.duo__value {\n  margin: 8px 0 5px;\n  font-size: 23px;\n  font-weight: 750;\n  letter-spacing: -.8px;\n  font-variant-numeric: tabular-nums;\n}\n.duo__value--cost { color: var(--ink-2); }\n.duo__meta { margin: 0; font-size: 11.5px; color: var(--muted); font-weight: 600; }\n\n.chartcard { margin-top: 12px; padding: 16px; }\n.chartcard__hint { font-size: 11.5px; color: var(--muted); font-weight: 600; }\n.chart { display: block; }\n.chart svg { display: block; width: 100%; height: auto; overflow: visible; }\n.chart .bar { transition: height .5s cubic-bezier(.3, .9, .3, 1), y .5s cubic-bezier(.3, .9, .3, 1); }\n.chart .bar-label { font-size: 10px; font-weight: 650; fill: var(--muted); }\n.chart .bar-value { font-size: 9.5px; font-weight: 700; fill: var(--ink-2); }\n.chart .grid-line { stroke: var(--line); stroke-width: 1; }\n\n.ranklist { list-style: none; margin: 0; padding: 4px 16px; }\n.rankrow {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 13px 0;\n  border-bottom: 1px solid var(--line);\n}\n.rankrow:last-child { border-bottom: 0; }\n.rankrow__no {\n  width: 26px;\n  height: 26px;\n  border-radius: 9px;\n  display: grid;\n  place-items: center;\n  background: var(--blue-50);\n  color: var(--blue-700);\n  font-size: 12px;\n  font-weight: 750;\n  flex: none;\n}\n.rankrow__body { flex: 1; min-width: 0; }\n.rankrow__name {\n  margin: 0 0 3px;\n  font-size: 14.5px;\n  font-weight: 650;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.rankrow__meta { margin: 0; font-size: 11.5px; color: var(--muted); }\n.rankrow__margin {\n  font-size: 14px;\n  font-weight: 750;\n  color: var(--green-2);\n  font-variant-numeric: tabular-nums;\n}\n\n/* ============================= TAB BAR ============================= */\n.tabbar {\n  flex: none;\n  height: var(--tab-h);\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  align-items: start;\n  padding: 9px 6px 0;\n  background: rgba(255, 255, 255, .92);\n  backdrop-filter: blur(18px) saturate(180%);\n  -webkit-backdrop-filter: blur(18px) saturate(180%);\n  border-top: 1px solid rgba(210, 224, 240, .8);\n  position: relative;\n  z-index: 10;\n}\n.tab {\n  border: 0;\n  background: none;\n  cursor: pointer;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 4px;\n  padding: 6px 2px;\n  color: #93A3B6;\n  transition: color .2s ease, transform .14s ease;\n}\n.tab span { font-size: 10.5px; font-weight: 620; letter-spacing: .1px; }\n.tab .icon { width: 23px; height: 23px; }\n.tab:active { transform: scale(.92); }\n.tab.is-on { color: var(--blue-600); }\n.tab.is-on .icon { stroke-width: 2.1; }\n\n.homebar {\n  flex: none;\n  height: 22px;\n  background: rgba(255, 255, 255, .92);\n  position: relative;\n  z-index: 10;\n}\n.homebar::after {\n  content: \"\";\n  position: absolute;\n  left: 50%;\n  top: 3px;\n  transform: translateX(-50%);\n  width: 134px;\n  height: 5px;\n  border-radius: 5px;\n  background: #0B1524;\n  opacity: .82;\n}\n\n/* ============================== TOAST ============================== */\n.toast {\n  position: absolute;\n  left: 20px;\n  right: 20px;\n  bottom: calc(var(--tab-h) + 22px);\n  z-index: 30;\n  background: rgba(13, 27, 44, .95);\n  color: #fff;\n  font-size: 13.5px;\n  font-weight: 600;\n  line-height: 1.4;\n  padding: 13px 16px;\n  border-radius: 14px;\n  box-shadow: 0 12px 30px rgba(8, 22, 40, .35);\n  opacity: 0;\n  transform: translateY(14px);\n  pointer-events: none;\n  transition: opacity .25s ease, transform .25s ease;\n}\n.toast.is-on { opacity: 1; transform: none; }\n\n/* ============================== PRINT ============================== */\n.printsheet { display: none; }\n\n@media print {\n  body { background: #fff; }\n  .stage { display: none; }\n  .printsheet {\n    display: block;\n    text-align: center;\n    padding: 40px;\n    font-family: var(--font);\n  }\n  .printsheet h1 { font-size: 20px; margin: 0 0 4px; }\n  .printsheet .ps-sub { font-size: 12px; color: #555; margin: 0 0 24px; }\n  .printsheet svg { width: 260px; height: 260px; }\n  .printsheet dl { max-width: 320px; margin: 24px auto 0; text-align: left; font-size: 13px; }\n  .printsheet dl div { display: flex; justify-content: space-between; padding: 6px 0; border-bottom: 1px solid #ddd; }\n  .printsheet dt { color: #666; }\n  .printsheet dd { margin: 0; font-weight: 700; }\n}\n\n/* =========================== RESPONSIVE =========================== */\n@media (max-width: 460px), (max-height: 700px) {\n  .stage { padding: 0; }\n  .phone {\n    width: 100%;\n    height: 100vh;\n    height: 100dvh;\n    max-height: none;\n    border: 0;\n    border-radius: 0;\n    box-shadow: none;\n  }\n  .statusbar__notch { display: none; }\n  .homebar { height: max(18px, env(safe-area-inset-bottom)); }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after {\n    animation-duration: .001ms !important;\n    animation-iteration-count: 1 !important;\n    transition-duration: .001ms !important;\n  }\n}\n\n/* ====================== NATIVE SHELL (APK / WebView) ======================\n   Inside the Expo shell the real device supplies the status bar and gesture\n   bar, so the simulated ones are dropped and the app runs edge to edge.\n   ======================================================================== */\nhtml.is-native, html.is-native body { height: 100%; overflow: hidden; }\n\nhtml.is-native .stage { padding: 0; min-height: 100%; }\n\nhtml.is-native .phone {\n  width: 100%;\n  height: 100%;\n  max-height: none;\n  border: 0;\n  border-radius: 0;\n  box-shadow: none;\n}\n\n/* The device draws these for real. */\nhtml.is-native .statusbar,\nhtml.is-native .homebar { display: none; }\n\n/* Controls that were clearing the simulated home indicator no longer need to. */\nhtml.is-native .tabbar { padding-bottom: env(safe-area-inset-bottom, 0px); }\nhtml.is-native .sheet--modal { padding-bottom: calc(24px + env(safe-area-inset-bottom, 0px)); }\nhtml.is-native .toast { bottom: calc(var(--tab-h) + 14px + env(safe-area-inset-bottom, 0px)); }\n\n</style>\n<script>\n  /* The native shell sets this before any document script runs, so the mock\n     status bar and phone frame can be dropped before first paint. */\n  if (window.__PHARMACHECK_NATIVE__) document.documentElement.classList.add('is-native');\n</script>\n</head>\n<body>\n\n<!-- ============================ ICON SPRITE ============================ -->\n<svg class=\"sprite\" aria-hidden=\"true\" focusable=\"false\">\n  <symbol id=\"i-grid\" viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"3\" width=\"7.5\" height=\"7.5\" rx=\"2\"/><rect x=\"13.5\" y=\"3\" width=\"7.5\" height=\"7.5\" rx=\"2\"/><rect x=\"3\" y=\"13.5\" width=\"7.5\" height=\"7.5\" rx=\"2\"/><rect x=\"13.5\" y=\"13.5\" width=\"7.5\" height=\"7.5\" rx=\"2\"/></symbol>\n  <symbol id=\"i-rx\" viewBox=\"0 0 24 24\"><path d=\"M19 21H5a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h9l6 6v11a1 1 0 0 1-1 1Z\"/><path d=\"M14 3v6h6\"/><path d=\"M8 12h4.2a1.9 1.9 0 0 1 0 3.8H8V12Zm0 3.8V19\"/><path d=\"m12.6 15.8 3.4 3.4m0-3.4-3.4 3.4\"/></symbol>\n  <symbol id=\"i-box\" viewBox=\"0 0 24 24\"><path d=\"M21 8.4v7.2a1.6 1.6 0 0 1-.85 1.41l-7.2 3.86a2 2 0 0 1-1.9 0l-7.2-3.86A1.6 1.6 0 0 1 3 15.6V8.4a1.6 1.6 0 0 1 .85-1.41l7.2-3.86a2 2 0 0 1 1.9 0l7.2 3.86A1.6 1.6 0 0 1 21 8.4Z\"/><path d=\"m3.3 7.5 8.7 4.6 8.7-4.6M12 12.1V21\"/></symbol>\n  <symbol id=\"i-chart\" viewBox=\"0 0 24 24\"><path d=\"M4 20V10m5 10V4m5 16v-7m5 7V8\"/></symbol>\n  <symbol id=\"i-scan\" viewBox=\"0 0 24 24\"><path d=\"M3 8V5.5A2.5 2.5 0 0 1 5.5 3H8M16 3h2.5A2.5 2.5 0 0 1 21 5.5V8M21 16v2.5a2.5 2.5 0 0 1-2.5 2.5H16M8 21H5.5A2.5 2.5 0 0 1 3 18.5V16\"/><path d=\"M7 8v8m3.5-8v8M14 8v8m3.5-8v8\"/></symbol>\n  <symbol id=\"i-pen\" viewBox=\"0 0 24 24\"><path d=\"M16.5 3.5a2.12 2.12 0 0 1 3 3L8 18l-4 1 1-4Z\"/><path d=\"M14.5 5.5l3 3\"/></symbol>\n  <symbol id=\"i-search\" viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-3.6-3.6\"/></symbol>\n  <symbol id=\"i-plus\" viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12h14\"/></symbol>\n  <symbol id=\"i-bell\" viewBox=\"0 0 24 24\"><path d=\"M18 8a6 6 0 1 0-12 0c0 6-2 7-2 7h16s-2-1-2-7Z\"/><path d=\"M13.7 20a2 2 0 0 1-3.4 0\"/></symbol>\n  <symbol id=\"i-chevron\" viewBox=\"0 0 24 24\"><path d=\"m9 5 7 7-7 7\"/></symbol>\n  <symbol id=\"i-back\" viewBox=\"0 0 24 24\"><path d=\"M15 5 8 12l7 7\"/></symbol>\n  <symbol id=\"i-close\" viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12M18 6 6 18\"/></symbol>\n  <symbol id=\"i-check\" viewBox=\"0 0 24 24\"><path d=\"m4 12.5 5.2 5.2L20 7\"/></symbol>\n  <symbol id=\"i-flash\" viewBox=\"0 0 24 24\"><path d=\"M13 2 4 14h7l-1 8 9-12h-7l1-8Z\"/></symbol>\n  <symbol id=\"i-flash-off\" viewBox=\"0 0 24 24\"><path d=\"M13 2 8.6 7.9M11 14H4L8 8.6M13.5 10H20l-6.2 8.3-.4 3.7\"/><path d=\"M3 3l18 18\"/></symbol>\n  <symbol id=\"i-gallery\" viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"2.5\"/><circle cx=\"8.5\" cy=\"9.5\" r=\"1.6\"/><path d=\"m4 17 4.5-4.5a2 2 0 0 1 2.8 0L16 17m-1-2 1.6-1.6a2 2 0 0 1 2.8 0L21 15\"/></symbol>\n  <symbol id=\"i-flip\" viewBox=\"0 0 24 24\"><path d=\"M3 10a7 7 0 0 1 11.9-5M21 14a7 7 0 0 1-11.9 5\"/><path d=\"M3 5v5h5M21 19v-5h-5\"/></symbol>\n  <symbol id=\"i-share\" viewBox=\"0 0 24 24\"><path d=\"M12 15V3m0 0L8.5 6.5M12 3l3.5 3.5\"/><path d=\"M5 12v7a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-7\"/></symbol>\n  <symbol id=\"i-pill\" viewBox=\"0 0 24 24\"><rect x=\"2.5\" y=\"8\" width=\"19\" height=\"8\" rx=\"4\" transform=\"rotate(-45 12 12)\"/><path d=\"m9 9 6 6\"/></symbol>\n  <symbol id=\"i-alert\" viewBox=\"0 0 24 24\"><path d=\"M12 3.5 21 19H3l9-15.5Z\"/><path d=\"M12 10v4m0 3h.01\"/></symbol>\n  <symbol id=\"i-trend\" viewBox=\"0 0 24 24\"><path d=\"M3 17 9.5 10.5l4 4L21 7\"/><path d=\"M15 7h6v6\"/></symbol>\n  <symbol id=\"i-user\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4.5 20a7.5 7.5 0 0 1 15 0\"/></symbol>\n  <symbol id=\"i-dose\" viewBox=\"0 0 24 24\"><path d=\"M12 3v4M8 7h8l-1 13.2a1 1 0 0 1-1 .8h-4a1 1 0 0 1-1-.8L8 7Z\"/><path d=\"M8.4 13h7.2\"/></symbol>\n  <symbol id=\"i-hash\" viewBox=\"0 0 24 24\"><path d=\"M10 3 8 21M16 3l-2 18M3.5 8.5h17M3 15.5h17\"/></symbol>\n  <symbol id=\"i-clock\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5.2l3.4 2\"/></symbol>\n  <symbol id=\"i-filter\" viewBox=\"0 0 24 24\"><path d=\"M3 5h18l-7 8v6l-4 2v-8L3 5Z\"/></symbol>\n</svg>\n\n<div class=\"stage\">\n  <div class=\"phone\" role=\"application\" aria-label=\"PharmaCheck\">\n\n    <!-- ========================= STATUS BAR ========================= -->\n    <div class=\"statusbar\">\n      <span class=\"statusbar__time\" id=\"clock\">9:41</span>\n      <span class=\"statusbar__notch\"></span>\n      <span class=\"statusbar__icons\">\n        <svg viewBox=\"0 0 20 12\" class=\"sb-signal\"><rect x=\"0\" y=\"8\" width=\"3\" height=\"4\" rx=\"1\"/><rect x=\"4.5\" y=\"5.5\" width=\"3\" height=\"6.5\" rx=\"1\"/><rect x=\"9\" y=\"3\" width=\"3\" height=\"9\" rx=\"1\"/><rect x=\"13.5\" y=\"0\" width=\"3\" height=\"12\" rx=\"1\"/></svg>\n        <svg viewBox=\"0 0 16 12\" class=\"sb-wifi\"><path d=\"M8 10.4 6 8a2.9 2.9 0 0 1 4 0l-2 2.4Z\"/><path d=\"M3.6 5.6a6.6 6.6 0 0 1 8.8 0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"/><path d=\"M1.2 3.1a10.2 10.2 0 0 1 13.6 0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"/></svg>\n        <svg viewBox=\"0 0 26 12\" class=\"sb-batt\"><rect x=\"0.6\" y=\"0.6\" width=\"21\" height=\"10.8\" rx=\"3.2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\" opacity=\".45\"/><rect x=\"2.4\" y=\"2.4\" width=\"15\" height=\"7.2\" rx=\"2\" /><path d=\"M23.4 4.2v3.6a2.2 2.2 0 0 0 0-3.6Z\" opacity=\".45\"/></svg>\n      </span>\n    </div>\n\n    <main class=\"viewport\" id=\"viewport\">\n\n      <!-- ===================== 1. DASHBOARD ===================== -->\n      <section class=\"screen screen--scroll is-active\" id=\"screen-dashboard\" aria-label=\"Dashboard\">\n        <header class=\"apphead\">\n          <div>\n            <p class=\"apphead__date\" id=\"today-label\">Thursday, 14 August</p>\n            <h1 class=\"apphead__title\">Welcome, Sarah</h1>\n            <p class=\"apphead__sub\">PharmaCheck Central · On duty</p>\n          </div>\n          <div class=\"apphead__actions\">\n            <button class=\"iconbtn iconbtn--ghost\" type=\"button\" id=\"bell\" aria-label=\"Notifications\">\n              <svg class=\"icon\"><use href=\"#i-bell\"/></svg>\n              <span class=\"dot-badge\"></span>\n            </button>\n            <div class=\"avatar\" aria-hidden=\"true\">SK</div>\n          </div>\n        </header>\n\n        <div class=\"quickgrid\">\n          <button class=\"quicktile\" type=\"button\" data-go=\"scanner\">\n            <span class=\"quicktile__icon quicktile__icon--blue\"><svg class=\"icon\"><use href=\"#i-scan\"/></svg></span>\n            <span class=\"quicktile__label\">Scan<br>Prescription</span>\n          </button>\n          <button class=\"quicktile\" type=\"button\" data-go=\"inventory\">\n            <span class=\"quicktile__icon quicktile__icon--teal\"><svg class=\"icon\"><use href=\"#i-box\"/></svg></span>\n            <span class=\"quicktile__label\">Inventory</span>\n          </button>\n          <button class=\"quicktile\" type=\"button\" data-go=\"manual\">\n            <span class=\"quicktile__icon quicktile__icon--violet\"><svg class=\"icon\"><use href=\"#i-pen\"/></svg></span>\n            <span class=\"quicktile__label\">Manual<br>Entry</span>\n          </button>\n        </div>\n\n        <div class=\"section-head\">\n          <h2 class=\"section-title\">Today’s Summary</h2>\n          <button class=\"linkbtn\" type=\"button\" data-go=\"reports\">View reports <svg class=\"icon icon--xs\"><use href=\"#i-chevron\"/></svg></button>\n        </div>\n\n        <div class=\"metricgrid\">\n          <div class=\"card metric\">\n            <p class=\"metric__label\">Prescriptions Filled</p>\n            <p class=\"metric__value\">42</p>\n            <p class=\"metric__delta metric__delta--up\"><svg class=\"icon icon--xs\"><use href=\"#i-trend\"/></svg> 8 more than yesterday</p>\n          </div>\n          <div class=\"card metric\">\n            <p class=\"metric__label\">Low Stock Items</p>\n            <p class=\"metric__value metric__value--alert\" id=\"dash-low\">—</p>\n            <p class=\"metric__delta metric__delta--down\"><svg class=\"icon icon--xs\"><use href=\"#i-alert\"/></svg> Reorder required</p>\n          </div>\n          <div class=\"card metric\">\n            <p class=\"metric__label\">Awaiting Verification</p>\n            <p class=\"metric__value\">3</p>\n            <p class=\"metric__delta\"><svg class=\"icon icon--xs\"><use href=\"#i-clock\"/></svg> Oldest 12 min ago</p>\n          </div>\n          <div class=\"card metric\">\n            <p class=\"metric__label\">Revenue Today</p>\n            <p class=\"metric__value\">$4,280</p>\n            <p class=\"metric__delta metric__delta--up\"><svg class=\"icon icon--xs\"><use href=\"#i-trend\"/></svg> 6.2% vs average</p>\n          </div>\n        </div>\n\n        <div class=\"section-head\">\n          <h2 class=\"section-title\">Recent Activity</h2>\n        </div>\n        <ul class=\"card activity\" id=\"activity-list\">\n          <li class=\"activity__row\">\n            <span class=\"activity__icon\"><svg class=\"icon\"><use href=\"#i-pill\"/></svg></span>\n            <span class=\"activity__body\">\n              <span class=\"activity__name\">Amoxicillin 500mg</span>\n              <span class=\"activity__meta\">M. Gonzalez · 21 capsules</span>\n            </span>\n            <span class=\"badge badge--green\">Filled</span>\n          </li>\n          <li class=\"activity__row\">\n            <span class=\"activity__icon\"><svg class=\"icon\"><use href=\"#i-pill\"/></svg></span>\n            <span class=\"activity__body\">\n              <span class=\"activity__name\">Metformin 850mg</span>\n              <span class=\"activity__meta\">J. Whitfield · 60 tablets</span>\n            </span>\n            <span class=\"badge badge--amber\">Pending</span>\n          </li>\n          <li class=\"activity__row\">\n            <span class=\"activity__icon\"><svg class=\"icon\"><use href=\"#i-pill\"/></svg></span>\n            <span class=\"activity__body\">\n              <span class=\"activity__name\">Salbutamol Inhaler</span>\n              <span class=\"activity__meta\">A. Rahman · 1 unit</span>\n            </span>\n            <span class=\"badge badge--green\">Filled</span>\n          </li>\n        </ul>\n      </section>\n\n      <!-- ===================== 2. SCANNER ===================== -->\n      <section class=\"screen screen--camera\" id=\"screen-scanner\" aria-label=\"Prescription scanner\">\n        <div class=\"camera\">\n          <video class=\"camera__feed\" id=\"camera-feed\" playsinline muted autoplay></video>\n\n          <!-- Simulated document, shown until a real camera stream starts -->\n          <div class=\"camera__mock\" id=\"camera-mock\">\n            <div class=\"scene\">\n              <div class=\"paper\">\n                <div class=\"paper__head\">\n                  <div>\n                    <p class=\"paper__clinic\">NORTHSIDE MEDICAL CENTRE</p>\n                    <p class=\"paper__line paper__line--sm\">Dr. E. Okafor · Lic. 44-208-119</p>\n                  </div>\n                  <div class=\"paper__rx\">℞</div>\n                </div>\n                <div class=\"paper__rule\"></div>\n                <p class=\"paper__line\" style=\"width:78%\"></p>\n                <p class=\"paper__line\" style=\"width:54%\"></p>\n                <div class=\"paper__qr\" id=\"mock-qr\"></div>\n                <p class=\"paper__line\" style=\"width:66%\"></p>\n                <p class=\"paper__line paper__line--sm\" style=\"width:44%\"></p>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"camera__vignette\"></div>\n          <div class=\"flash-burst\" id=\"flash-burst\"></div>\n\n          <!-- Top bar -->\n          <div class=\"camtop\">\n            <button class=\"iconbtn iconbtn--glass\" type=\"button\" data-go=\"dashboard\" aria-label=\"Close scanner\">\n              <svg class=\"icon\"><use href=\"#i-close\"/></svg>\n            </button>\n            <div class=\"camtop__title\">\n              <span>Scan Prescription</span>\n              <small id=\"camera-source\">Simulated feed</small>\n            </div>\n            <button class=\"iconbtn iconbtn--glass\" type=\"button\" id=\"flash-toggle\" aria-pressed=\"false\" aria-label=\"Toggle flash\">\n              <svg class=\"icon\" id=\"flash-icon\"><use href=\"#i-flash-off\"/></svg>\n            </button>\n          </div>\n\n          <!-- Viewfinder -->\n          <div class=\"finder\" id=\"finder\">\n            <span class=\"finder__corner finder__corner--tl\"></span>\n            <span class=\"finder__corner finder__corner--tr\"></span>\n            <span class=\"finder__corner finder__corner--bl\"></span>\n            <span class=\"finder__corner finder__corner--br\"></span>\n            <span class=\"finder__beam\" id=\"finder-beam\"></span>\n            <div class=\"finder__success\" id=\"finder-success\" aria-hidden=\"true\">\n              <span class=\"finder__check\"><svg class=\"icon\"><use href=\"#i-check\"/></svg></span>\n            </div>\n          </div>\n\n          <p class=\"camera__hint\" id=\"camera-hint\">Align QR Code within the frame</p>\n\n          <!-- Bottom controls -->\n          <div class=\"camctl\">\n            <button class=\"iconbtn iconbtn--glass\" type=\"button\" data-toast=\"Photo library is not available in this demo\" aria-label=\"Choose from library\">\n              <svg class=\"icon\"><use href=\"#i-gallery\"/></svg>\n            </button>\n            <button class=\"shutter\" type=\"button\" id=\"shutter\" aria-label=\"Capture prescription\">\n              <span class=\"shutter__ring\"></span>\n              <span class=\"shutter__core\"></span>\n            </button>\n            <button class=\"iconbtn iconbtn--glass\" type=\"button\" id=\"camera-flip\" aria-label=\"Switch camera\">\n              <svg class=\"icon\"><use href=\"#i-flip\"/></svg>\n            </button>\n          </div>\n\n          <!-- Result sheet -->\n          <div class=\"sheet\" id=\"scan-sheet\" aria-hidden=\"true\">\n            <div class=\"sheet__grab\"></div>\n            <div class=\"sheet__head\">\n              <span class=\"sheet__badge\"><svg class=\"icon icon--xs\"><use href=\"#i-check\"/></svg> Code verified</span>\n              <span class=\"sheet__code\" id=\"scan-code\">PC-2026-0481</span>\n            </div>\n            <dl class=\"kv\">\n              <div class=\"kv__row\"><dt>Patient</dt><dd>Maria Gonzalez</dd></div>\n              <div class=\"kv__row\"><dt>Medication</dt><dd>Amoxicillin 500mg</dd></div>\n              <div class=\"kv__row\"><dt>Dosage</dt><dd>1 capsule, 3× daily</dd></div>\n              <div class=\"kv__row\"><dt>Quantity</dt><dd>21 capsules</dd></div>\n              <div class=\"kv__row\"><dt>Prescriber</dt><dd>Dr. E. Okafor</dd></div>\n            </dl>\n            <div class=\"sheet__actions\">\n              <button class=\"btn btn--ghost\" type=\"button\" id=\"scan-dismiss\">Rescan</button>\n              <button class=\"btn btn--primary\" type=\"button\" id=\"scan-fill\">Fill Prescription</button>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- ===================== 3. MANUAL ENTRY ===================== -->\n      <section class=\"screen screen--scroll\" id=\"screen-manual\" aria-label=\"Manual entry\">\n        <header class=\"apphead apphead--compact\">\n          <button class=\"iconbtn iconbtn--ghost\" type=\"button\" data-go=\"scanner\" aria-label=\"Back to scanner\">\n            <svg class=\"icon\"><use href=\"#i-back\"/></svg>\n          </button>\n          <div>\n            <h1 class=\"apphead__title apphead__title--sm\">Manual Entry</h1>\n            <p class=\"apphead__sub\">Create a prescription code by hand</p>\n          </div>\n        </header>\n\n        <form class=\"card form\" id=\"rx-form\" novalidate>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"f-patient\">Patient Name</label>\n            <div class=\"field__control\">\n              <svg class=\"icon field__icon\"><use href=\"#i-user\"/></svg>\n              <input id=\"f-patient\" name=\"patient\" type=\"text\" autocomplete=\"off\" placeholder=\"e.g. Maria Gonzalez\">\n            </div>\n            <p class=\"field__error\" data-error-for=\"patient\"></p>\n          </div>\n\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"f-medication\">Medication Name</label>\n            <div class=\"field__control\">\n              <svg class=\"icon field__icon\"><use href=\"#i-pill\"/></svg>\n              <input id=\"f-medication\" name=\"medication\" type=\"text\" autocomplete=\"off\" placeholder=\"e.g. Amoxicillin 500mg\" list=\"med-suggestions\">\n            </div>\n            <datalist id=\"med-suggestions\"></datalist>\n            <p class=\"field__error\" data-error-for=\"medication\"></p>\n          </div>\n\n          <div class=\"field-row\">\n            <div class=\"field\">\n              <label class=\"field__label\" for=\"f-dosage\">Dosage</label>\n              <div class=\"field__control\">\n                <svg class=\"icon field__icon\"><use href=\"#i-dose\"/></svg>\n                <input id=\"f-dosage\" name=\"dosage\" type=\"text\" autocomplete=\"off\" placeholder=\"1 cap, 3× daily\">\n              </div>\n              <p class=\"field__error\" data-error-for=\"dosage\"></p>\n            </div>\n            <div class=\"field\">\n              <label class=\"field__label\" for=\"f-quantity\">Quantity</label>\n              <div class=\"field__control\">\n                <svg class=\"icon field__icon\"><use href=\"#i-hash\"/></svg>\n                <input id=\"f-quantity\" name=\"quantity\" type=\"number\" inputmode=\"numeric\" min=\"1\" step=\"1\" placeholder=\"21\">\n              </div>\n              <p class=\"field__error\" data-error-for=\"quantity\"></p>\n            </div>\n          </div>\n\n          <button class=\"btn btn--primary btn--block btn--lg\" type=\"submit\">\n            Generate Prescription Code\n          </button>\n        </form>\n\n        <p class=\"hintnote\" id=\"manual-hint\">\n          <svg class=\"icon icon--xs\"><use href=\"#i-scan\"/></svg>\n          The generated code carries the prescription details, so it can be\n          scanned at collection without looking anything up.\n        </p>\n\n        <div class=\"card qrcard\" id=\"qr-result\" hidden>\n          <div class=\"qrcard__head\">\n            <div>\n              <p class=\"qrcard__label\">Prescription Code</p>\n              <p class=\"qrcard__code\" id=\"qr-code-text\">—</p>\n            </div>\n            <span class=\"badge badge--green\">Ready</span>\n          </div>\n          <div class=\"qrcard__frame\" id=\"qr-canvas\"></div>\n          <p class=\"qrcard__meta\" id=\"qr-meta\"></p>\n          <div class=\"qrcard__tools\">\n            <button class=\"btn btn--soft\" type=\"button\" id=\"qr-print\">\n              <svg class=\"icon icon--xs\"><use href=\"#i-share\"/></svg> Print / Share\n            </button>\n          </div>\n        </div>\n      </section>\n\n      <!-- ===================== 4. INVENTORY ===================== -->\n      <section class=\"screen screen--fixed\" id=\"screen-inventory\" aria-label=\"Inventory\">\n        <header class=\"apphead apphead--compact\">\n          <div>\n            <h1 class=\"apphead__title apphead__title--sm\">Inventory</h1>\n            <p class=\"apphead__sub\" id=\"inv-summary\">—</p>\n          </div>\n        </header>\n\n        <div class=\"searchbar\">\n          <svg class=\"icon searchbar__icon\"><use href=\"#i-search\"/></svg>\n          <input id=\"inv-search\" type=\"search\" placeholder=\"Search Medicine Stock\" aria-label=\"Search Medicine Stock\" autocomplete=\"off\">\n        </div>\n\n        <div class=\"chips\" role=\"tablist\" aria-label=\"Stock filter\">\n          <button class=\"chip is-on\" type=\"button\" role=\"tab\" aria-selected=\"true\" data-filter=\"all\">All items</button>\n          <button class=\"chip\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-filter=\"low\">Low stock</button>\n          <button class=\"chip\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-filter=\"expiring\">Expiring soon</button>\n        </div>\n\n        <div class=\"scrollarea\">\n          <ul class=\"stocklist\" id=\"stock-list\"></ul>\n          <p class=\"emptystate\" id=\"stock-empty\" hidden>No medicines match that search.</p>\n        </div>\n\n        <button class=\"fab\" type=\"button\" id=\"fab-add\" aria-label=\"Add stock\">\n          <svg class=\"icon\"><use href=\"#i-plus\"/></svg>\n        </button>\n      </section>\n\n      <!-- ===================== 5. REPORTS ===================== -->\n      <section class=\"screen screen--scroll\" id=\"screen-reports\" aria-label=\"Financial reports\">\n        <header class=\"apphead apphead--compact\">\n          <div>\n            <h1 class=\"apphead__title apphead__title--sm\">Financial Reports</h1>\n            <p class=\"apphead__sub\">Manager view · PharmaCheck Central</p>\n          </div>\n          <span class=\"badge badge--blue\">Manager</span>\n        </header>\n\n        <div class=\"segmented\" role=\"tablist\" aria-label=\"Reporting period\">\n          <button class=\"segmented__btn is-on\" type=\"button\" role=\"tab\" aria-selected=\"true\" data-period=\"daily\">Daily</button>\n          <button class=\"segmented__btn\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-period=\"weekly\">Weekly</button>\n          <button class=\"segmented__btn\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-period=\"monthly\">Monthly</button>\n          <span class=\"segmented__pill\" id=\"segpill\"></span>\n        </div>\n\n        <div class=\"card profit\">\n          <p class=\"profit__label\">Net Profit Summary</p>\n          <p class=\"profit__value\" id=\"profit-value\">$0</p>\n          <p class=\"profit__trend\"><svg class=\"icon icon--xs\"><use href=\"#i-trend\"/></svg> <span id=\"profit-trend\">—</span></p>\n          <p class=\"profit__note\" id=\"profit-range\">—</p>\n        </div>\n\n        <div class=\"duo\">\n          <div class=\"card duo__card\">\n            <p class=\"duo__label\">Total Revenue</p>\n            <p class=\"duo__value\" id=\"revenue-value\">$0</p>\n            <p class=\"duo__meta\" id=\"revenue-meta\">—</p>\n          </div>\n          <div class=\"card duo__card\">\n            <p class=\"duo__label\">Total COGS</p>\n            <p class=\"duo__value duo__value--cost\" id=\"cogs-value\">$0</p>\n            <p class=\"duo__meta\" id=\"cogs-meta\">—</p>\n          </div>\n        </div>\n\n        <div class=\"card chartcard\">\n          <div class=\"section-head section-head--tight\">\n            <h2 class=\"section-title section-title--sm\">Sales Trend</h2>\n            <span class=\"chartcard__hint\">Last 4 weeks</span>\n          </div>\n          <div class=\"chart\" id=\"chart\"></div>\n        </div>\n\n        <div class=\"section-head\">\n          <h2 class=\"section-title\">Top Profitable Items</h2>\n          <span class=\"section-note\">Margin</span>\n        </div>\n        <ul class=\"card ranklist\" id=\"rank-list\"></ul>\n      </section>\n\n    </main>\n\n    <!-- ========================== TAB BAR ========================== -->\n    <nav class=\"tabbar\" aria-label=\"Primary\">\n      <button class=\"tab is-on\" type=\"button\" data-go=\"dashboard\" aria-current=\"page\">\n        <svg class=\"icon\"><use href=\"#i-grid\"/></svg><span>Dashboard</span>\n      </button>\n      <button class=\"tab\" type=\"button\" data-go=\"scanner\">\n        <svg class=\"icon\"><use href=\"#i-rx\"/></svg><span>Prescriptions</span>\n      </button>\n      <button class=\"tab\" type=\"button\" data-go=\"inventory\">\n        <svg class=\"icon\"><use href=\"#i-box\"/></svg><span>Inventory</span>\n      </button>\n      <button class=\"tab\" type=\"button\" data-go=\"reports\">\n        <svg class=\"icon\"><use href=\"#i-chart\"/></svg><span>Reports</span>\n      </button>\n    </nav>\n    <div class=\"homebar\" aria-hidden=\"true\"></div>\n\n    <!-- ===================== ADD-STOCK SHEET ===================== -->\n    <div class=\"scrim\" id=\"scrim\" hidden></div>\n    <div class=\"sheet sheet--modal\" id=\"stock-sheet\" aria-hidden=\"true\" role=\"dialog\" aria-label=\"Add stock\">\n      <div class=\"sheet__grab\"></div>\n      <h2 class=\"sheet__title\">Add Stock</h2>\n      <form id=\"stock-form\" novalidate>\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"s-name\">Medicine</label>\n          <div class=\"field__control\">\n            <svg class=\"icon field__icon\"><use href=\"#i-pill\"/></svg>\n            <input id=\"s-name\" name=\"name\" type=\"text\" placeholder=\"e.g. Amoxicillin 500mg\" list=\"med-suggestions\" autocomplete=\"off\">\n          </div>\n          <p class=\"field__error\" data-error-for=\"name\"></p>\n        </div>\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"s-qty\">Units received</label>\n          <div class=\"field__control\">\n            <svg class=\"icon field__icon\"><use href=\"#i-hash\"/></svg>\n            <input id=\"s-qty\" name=\"qty\" type=\"number\" inputmode=\"numeric\" min=\"1\" step=\"1\" placeholder=\"120\">\n          </div>\n          <p class=\"field__error\" data-error-for=\"qty\"></p>\n        </div>\n        <div class=\"sheet__actions\">\n          <button class=\"btn btn--ghost\" type=\"button\" id=\"stock-cancel\">Cancel</button>\n          <button class=\"btn btn--primary\" type=\"submit\">Add to Inventory</button>\n        </div>\n      </form>\n    </div>\n\n    <div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n  </div>\n</div>\n\n<!-- Print-only sheet for the generated prescription code -->\n<div class=\"printsheet\" id=\"printsheet\" aria-hidden=\"true\"></div>\n\n<script>\n/*\n * qr.js — minimal QR Code (Model 2) encoder.\n *\n * Byte mode, error correction level M, versions 1-10 (up to 211 characters).\n * Produces a boolean module matrix that PharmaCheck renders as an SVG.\n *\n * Written from the ISO/IEC 18004 spec: GF(256) Reed-Solomon, block\n * interleaving, the eight mask patterns and the four penalty rules.\n */\n(function (root, factory) {\n  var api = factory();\n  if (typeof module === 'object' && module.exports) module.exports = api;\n  else root.QRCodeGen = api;\n})(typeof self !== 'undefined' ? self : this, function () {\n  'use strict';\n\n  /* ------------------------------------------------------------------ *\n   * Version / error-correction tables (level M only)\n   * [ecCodewordsPerBlock, blocksInGroup1, dataPerBlock1, blocksInGroup2, dataPerBlock2]\n   * ------------------------------------------------------------------ */\n  var EC_TABLE_M = {\n    1: [10, 1, 16, 0, 0],\n    2: [16, 1, 28, 0, 0],\n    3: [26, 1, 44, 0, 0],\n    4: [18, 2, 32, 0, 0],\n    5: [24, 2, 43, 0, 0],\n    6: [16, 4, 27, 0, 0],\n    7: [18, 4, 31, 0, 0],\n    8: [22, 2, 38, 2, 39],\n    9: [22, 3, 36, 2, 37],\n    10: [26, 4, 43, 1, 44]\n  };\n\n  var ALIGNMENT = {\n    1: [],\n    2: [6, 18],\n    3: [6, 22],\n    4: [6, 26],\n    5: [6, 30],\n    6: [6, 34],\n    7: [6, 22, 38],\n    8: [6, 24, 42],\n    9: [6, 26, 46],\n    10: [6, 28, 50]\n  };\n\n  var MAX_VERSION = 10;\n\n  function dataCodewords(version) {\n    var t = EC_TABLE_M[version];\n    return t[1] * t[2] + t[3] * t[4];\n  }\n\n  /* Characters that fit in byte mode for a given version. The header is a\n   * 4-bit mode indicator plus an 8-bit length (16-bit from version 10). */\n  function byteCapacity(version) {\n    var headerBits = 4 + (version < 10 ? 8 : 16);\n    return dataCodewords(version) - Math.ceil(headerBits / 8);\n  }\n\n  /* ------------------------------------------------------------------ *\n   * GF(256) arithmetic, primitive polynomial 0x11D\n   * ------------------------------------------------------------------ */\n  var EXP = new Uint8Array(512);\n  var LOG = new Uint8Array(256);\n  (function initGaloisField() {\n    var x = 1;\n    for (var i = 0; i < 255; i++) {\n      EXP[i] = x;\n      LOG[x] = i;\n      x <<= 1;\n      if (x & 0x100) x ^= 0x11d;\n    }\n    for (var j = 255; j < 512; j++) EXP[j] = EXP[j - 255];\n  })();\n\n  function gfMul(a, b) {\n    if (a === 0 || b === 0) return 0;\n    return EXP[LOG[a] + LOG[b]];\n  }\n\n  /* Generator polynomial for `degree` error-correction codewords. */\n  function generatorPoly(degree) {\n    var poly = [1];\n    for (var d = 0; d < degree; d++) {\n      var next = new Array(poly.length + 1).fill(0);\n      for (var i = 0; i < poly.length; i++) {\n        next[i] ^= poly[i];\n        next[i + 1] ^= gfMul(poly[i], EXP[d]);\n      }\n      poly = next;\n    }\n    return poly;\n  }\n\n  function eccForBlock(block, ecLength) {\n    var gen = generatorPoly(ecLength);\n    var remainder = new Array(ecLength).fill(0);\n    for (var i = 0; i < block.length; i++) {\n      var factor = block[i] ^ remainder[0];\n      remainder.shift();\n      remainder.push(0);\n      for (var j = 0; j < ecLength; j++) {\n        remainder[j] ^= gfMul(gen[j + 1], factor);\n      }\n    }\n    return remainder;\n  }\n\n  /* ------------------------------------------------------------------ *\n   * BCH codes for the format and version information areas\n   * ------------------------------------------------------------------ */\n  function bch(value, generator, generatorBits) {\n    var shifted = value << (generatorBits - 1);\n    var remainder = shifted;\n    while (bitLength(remainder) >= generatorBits) {\n      remainder ^= generator << (bitLength(remainder) - generatorBits);\n    }\n    return shifted | remainder;\n  }\n\n  function bitLength(v) {\n    var n = 0;\n    while (v) {\n      n++;\n      v >>>= 1;\n    }\n    return n;\n  }\n\n  /* Level M is encoded as 00 in the format string. */\n  function formatBits(mask) {\n    var data = (0x00 << 3) | mask;\n    return (bch(data, 0x537, 11) ^ 0x5412) & 0x7fff;\n  }\n\n  function versionBits(version) {\n    return bch(version, 0x1f25, 13) & 0x3ffff;\n  }\n\n  /* ------------------------------------------------------------------ *\n   * Bit buffer\n   * ------------------------------------------------------------------ */\n  function BitBuffer() {\n    this.bits = [];\n  }\n  BitBuffer.prototype.put = function (value, length) {\n    for (var i = length - 1; i >= 0; i--) this.bits.push((value >>> i) & 1);\n  };\n\n  function toUtf8Bytes(text) {\n    var out = [];\n    var encoded = encodeURIComponent(text);\n    for (var i = 0; i < encoded.length; i++) {\n      if (encoded[i] === '%') {\n        out.push(parseInt(encoded.substr(i + 1, 2), 16));\n        i += 2;\n      } else {\n        out.push(encoded.charCodeAt(i));\n      }\n    }\n    return out;\n  }\n\n  /* ------------------------------------------------------------------ *\n   * Encoding\n   * ------------------------------------------------------------------ */\n  function encodeData(bytes, version) {\n    var buffer = new BitBuffer();\n    buffer.put(0x4, 4); // byte mode\n    buffer.put(bytes.length, version < 10 ? 8 : 16);\n    for (var i = 0; i < bytes.length; i++) buffer.put(bytes[i], 8);\n\n    var capacityBits = dataCodewords(version) * 8;\n    var terminator = Math.min(4, capacityBits - buffer.bits.length);\n    buffer.put(0, terminator);\n    while (buffer.bits.length % 8 !== 0) buffer.bits.push(0);\n\n    var codewords = [];\n    for (var b = 0; b < buffer.bits.length; b += 8) {\n      var byte = 0;\n      for (var k = 0; k < 8; k++) byte = (byte << 1) | buffer.bits[b + k];\n      codewords.push(byte);\n    }\n    var pad = [0xec, 0x11];\n    var p = 0;\n    while (codewords.length < dataCodewords(version)) {\n      codewords.push(pad[p++ % 2]);\n    }\n    return codewords;\n  }\n\n  function interleave(codewords, version) {\n    var t = EC_TABLE_M[version];\n    var ecLength = t[0];\n    var blocks = [];\n    var offset = 0;\n    var g;\n\n    for (g = 0; g < t[1]; g++) {\n      blocks.push(codewords.slice(offset, offset + t[2]));\n      offset += t[2];\n    }\n    for (g = 0; g < t[3]; g++) {\n      blocks.push(codewords.slice(offset, offset + t[4]));\n      offset += t[4];\n    }\n\n    var eccBlocks = blocks.map(function (block) {\n      return eccForBlock(block, ecLength);\n    });\n\n    var result = [];\n    var maxData = Math.max(t[2], t[4]);\n    var i, j;\n    for (i = 0; i < maxData; i++) {\n      for (j = 0; j < blocks.length; j++) {\n        if (i < blocks[j].length) result.push(blocks[j][i]);\n      }\n    }\n    for (i = 0; i < ecLength; i++) {\n      for (j = 0; j < eccBlocks.length; j++) result.push(eccBlocks[j][i]);\n    }\n    return result;\n  }\n\n  /* ------------------------------------------------------------------ *\n   * Matrix construction\n   * ------------------------------------------------------------------ */\n  function createMatrix(size) {\n    var m = [];\n    for (var r = 0; r < size; r++) m.push(new Array(size).fill(null));\n    return m;\n  }\n\n  function placeFinder(matrix, row, col) {\n    for (var r = -1; r <= 7; r++) {\n      for (var c = -1; c <= 7; c++) {\n        var rr = row + r;\n        var cc = col + c;\n        if (rr < 0 || cc < 0 || rr >= matrix.length || cc >= matrix.length) continue;\n        var inRing = (r >= 0 && r <= 6 && (c === 0 || c === 6)) ||\n                     (c >= 0 && c <= 6 && (r === 0 || r === 6));\n        var inCore = r >= 2 && r <= 4 && c >= 2 && c <= 4;\n        matrix[rr][cc] = inRing || inCore;\n      }\n    }\n  }\n\n  function placeFunctionPatterns(matrix, version) {\n    var size = matrix.length;\n    var i;\n\n    placeFinder(matrix, 0, 0);\n    placeFinder(matrix, 0, size - 7);\n    placeFinder(matrix, size - 7, 0);\n\n    // Timing patterns\n    for (i = 8; i < size - 8; i++) {\n      var on = i % 2 === 0;\n      if (matrix[6][i] === null) matrix[6][i] = on;\n      if (matrix[i][6] === null) matrix[i][6] = on;\n    }\n\n    // Alignment patterns. Every combination of centre coordinates is used\n    // except the three that would land on a finder pattern; the ones that\n    // straddle a timing line legitimately overwrite it.\n    var positions = ALIGNMENT[version];\n    var last = positions.length - 1;\n    for (var a = 0; a < positions.length; a++) {\n      for (var b = 0; b < positions.length; b++) {\n        var onFinder = (a === 0 && b === 0) ||\n                       (a === 0 && b === last) ||\n                       (a === last && b === 0);\n        if (onFinder) continue;\n        var cr = positions[a];\n        var cc = positions[b];\n        for (var dr = -2; dr <= 2; dr++) {\n          for (var dc = -2; dc <= 2; dc++) {\n            var ring = Math.max(Math.abs(dr), Math.abs(dc));\n            matrix[cr + dr][cc + dc] = ring !== 1;\n          }\n        }\n      }\n    }\n\n    // Dark module\n    matrix[size - 8][8] = true;\n\n    // Reserve the format areas so data placement skips them\n    for (i = 0; i <= 8; i++) {\n      if (matrix[8][i] === null) matrix[8][i] = false;\n      if (matrix[i][8] === null) matrix[i][8] = false;\n    }\n    for (i = 0; i < 8; i++) {\n      if (matrix[8][size - 1 - i] === null) matrix[8][size - 1 - i] = false;\n      if (matrix[size - 1 - i][8] === null) matrix[size - 1 - i][8] = false;\n    }\n\n    // Reserve the version areas (version 7 and up)\n    if (version >= 7) {\n      for (i = 0; i < 6; i++) {\n        for (var k = 0; k < 3; k++) {\n          matrix[size - 11 + k][i] = false;\n          matrix[i][size - 11 + k] = false;\n        }\n      }\n    }\n  }\n\n  function placeData(matrix, reserved, bytes) {\n    var size = matrix.length;\n    var bitIndex = 0;\n    var totalBits = bytes.length * 8;\n    var upward = true;\n\n    for (var right = size - 1; right >= 1; right -= 2) {\n      if (right === 6) right--; // skip the vertical timing column\n      for (var step = 0; step < size; step++) {\n        var row = upward ? size - 1 - step : step;\n        for (var c = 0; c < 2; c++) {\n          var col = right - c;\n          if (reserved[row][col]) continue;\n          var bit = false;\n          if (bitIndex < totalBits) {\n            bit = ((bytes[bitIndex >> 3] >>> (7 - (bitIndex & 7))) & 1) === 1;\n            bitIndex++;\n          }\n          matrix[row][col] = bit;\n        }\n      }\n      upward = !upward;\n    }\n  }\n\n  function maskCondition(mask, row, col) {\n    switch (mask) {\n      case 0: return (row + col) % 2 === 0;\n      case 1: return row % 2 === 0;\n      case 2: return col % 3 === 0;\n      case 3: return (row + col) % 3 === 0;\n      case 4: return (Math.floor(row / 2) + Math.floor(col / 3)) % 2 === 0;\n      case 5: return ((row * col) % 2) + ((row * col) % 3) === 0;\n      case 6: return (((row * col) % 2) + ((row * col) % 3)) % 2 === 0;\n      case 7: return (((row + col) % 2) + ((row * col) % 3)) % 2 === 0;\n      default: return false;\n    }\n  }\n\n  function applyMask(matrix, reserved, mask) {\n    for (var r = 0; r < matrix.length; r++) {\n      for (var c = 0; c < matrix.length; c++) {\n        if (reserved[r][c]) continue;\n        if (maskCondition(mask, r, c)) matrix[r][c] = !matrix[r][c];\n      }\n    }\n  }\n\n  function placeFormatInfo(matrix, mask) {\n    var size = matrix.length;\n    var bits = formatBits(mask);\n    var i;\n\n    // First copy: down the left of the top-left finder, then along the top.\n    for (i = 0; i <= 5; i++) matrix[i][8] = ((bits >> i) & 1) === 1;\n    matrix[7][8] = ((bits >> 6) & 1) === 1;\n    matrix[8][8] = ((bits >> 7) & 1) === 1;\n    matrix[8][7] = ((bits >> 8) & 1) === 1;\n    for (i = 9; i <= 14; i++) matrix[8][14 - i] = ((bits >> i) & 1) === 1;\n\n    // Second copy: along the bottom-left, then the top-right.\n    for (i = 0; i <= 7; i++) matrix[8][size - 1 - i] = ((bits >> i) & 1) === 1;\n    for (i = 8; i <= 14; i++) matrix[size - 15 + i][8] = ((bits >> i) & 1) === 1;\n    matrix[size - 8][8] = true;\n  }\n\n  function placeVersionInfo(matrix, version) {\n    if (version < 7) return;\n    var size = matrix.length;\n    var bits = versionBits(version);\n    for (var i = 0; i < 18; i++) {\n      var bit = ((bits >> i) & 1) === 1;\n      var row = Math.floor(i / 3);\n      var col = size - 11 + (i % 3);\n      matrix[row][col] = bit;\n      matrix[col][row] = bit;\n    }\n  }\n\n  /* ------------------------------------------------------------------ *\n   * Mask penalty scoring (ISO/IEC 18004 rules 1-4)\n   * ------------------------------------------------------------------ */\n  function penalty(matrix) {\n    var size = matrix.length;\n    var score = 0;\n    var r, c, run, dark = 0;\n\n    // Rule 1 — runs of five or more same-coloured modules\n    for (r = 0; r < size; r++) {\n      run = 1;\n      for (c = 1; c < size; c++) {\n        if (matrix[r][c] === matrix[r][c - 1]) {\n          run++;\n          if (run === 5) score += 3;\n          else if (run > 5) score += 1;\n        } else run = 1;\n      }\n    }\n    for (c = 0; c < size; c++) {\n      run = 1;\n      for (r = 1; r < size; r++) {\n        if (matrix[r][c] === matrix[r - 1][c]) {\n          run++;\n          if (run === 5) score += 3;\n          else if (run > 5) score += 1;\n        } else run = 1;\n      }\n    }\n\n    // Rule 2 — 2x2 blocks of one colour\n    for (r = 0; r < size - 1; r++) {\n      for (c = 0; c < size - 1; c++) {\n        var v = matrix[r][c];\n        if (v === matrix[r][c + 1] && v === matrix[r + 1][c] && v === matrix[r + 1][c + 1]) {\n          score += 3;\n        }\n      }\n    }\n\n    // Rule 3 — finder-like patterns\n    var patternA = [true, false, true, true, true, false, true, false, false, false, false];\n    var patternB = [false, false, false, false, true, false, true, true, true, false, true];\n    function matches(get, start, pattern) {\n      for (var i = 0; i < pattern.length; i++) {\n        if (get(start + i) !== pattern[i]) return false;\n      }\n      return true;\n    }\n    for (r = 0; r < size; r++) {\n      for (c = 0; c <= size - 11; c++) {\n        var rowGet = (function (row) {\n          return function (idx) { return matrix[row][idx]; };\n        })(r);\n        if (matches(rowGet, c, patternA) || matches(rowGet, c, patternB)) score += 40;\n      }\n    }\n    for (c = 0; c < size; c++) {\n      for (r = 0; r <= size - 11; r++) {\n        var colGet = (function (col) {\n          return function (idx) { return matrix[idx][col]; };\n        })(c);\n        if (matches(colGet, r, patternA) || matches(colGet, r, patternB)) score += 40;\n      }\n    }\n\n    // Rule 4 — balance of dark and light modules\n    for (r = 0; r < size; r++) {\n      for (c = 0; c < size; c++) if (matrix[r][c]) dark++;\n    }\n    var percent = (dark * 100) / (size * size);\n    score += Math.floor(Math.abs(percent - 50) / 5) * 10;\n\n    return score;\n  }\n\n  function cloneMatrix(matrix) {\n    return matrix.map(function (row) { return row.slice(); });\n  }\n\n  /* ------------------------------------------------------------------ *\n   * Public API\n   * ------------------------------------------------------------------ */\n  function generate(text) {\n    var bytes = toUtf8Bytes(String(text));\n    var version = 0;\n    for (var v = 1; v <= MAX_VERSION; v++) {\n      if (bytes.length <= byteCapacity(v)) {\n        version = v;\n        break;\n      }\n    }\n    if (!version) {\n      throw new Error('Payload too long for QR versions 1-' + MAX_VERSION +\n        ' (max ' + byteCapacity(MAX_VERSION) + ' bytes, got ' + bytes.length + ').');\n    }\n\n    var size = version * 4 + 17;\n    var codewords = interleave(encodeData(bytes, version), version);\n\n    var base = createMatrix(size);\n    placeFunctionPatterns(base, version);\n    var reserved = base.map(function (row) {\n      return row.map(function (cell) { return cell !== null; });\n    });\n    placeData(base, reserved, codewords);\n\n    var best = null;\n    var bestScore = Infinity;\n    for (var mask = 0; mask < 8; mask++) {\n      var candidate = cloneMatrix(base);\n      applyMask(candidate, reserved, mask);\n      placeFormatInfo(candidate, mask);\n      placeVersionInfo(candidate, version);\n      var score = penalty(candidate);\n      if (score < bestScore) {\n        bestScore = score;\n        best = candidate;\n      }\n    }\n\n    return { version: version, size: size, modules: best };\n  }\n\n  /* Render a QR matrix as a standalone SVG string. */\n  function toSvg(text, options) {\n    var opts = options || {};\n    var quiet = opts.quietZone == null ? 3 : opts.quietZone;\n    var dark = opts.dark || '#0F1B2D';\n    var light = opts.light || '#FFFFFF';\n    var qr = generate(text);\n    var dim = qr.size + quiet * 2;\n    var path = [];\n\n    for (var r = 0; r < qr.size; r++) {\n      for (var c = 0; c < qr.size; c++) {\n        if (qr.modules[r][c]) {\n          path.push('M' + (c + quiet) + ' ' + (r + quiet) + 'h1v1h-1z');\n        }\n      }\n    }\n\n    return '<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 ' + dim + ' ' + dim +\n      '\" shape-rendering=\"crispEdges\" role=\"img\" aria-label=\"QR code\">' +\n      '<rect width=\"' + dim + '\" height=\"' + dim + '\" fill=\"' + light + '\"/>' +\n      '<path d=\"' + path.join('') + '\" fill=\"' + dark + '\"/></svg>';\n  }\n\n  /* Exposed so test/verify-qr.js can diff intermediate stages against a\n   * reference encoder. Not used by the app itself. */\n  function _stages(text) {\n    var bytes = toUtf8Bytes(String(text));\n    var version = 1;\n    while (version <= MAX_VERSION && bytes.length > byteCapacity(version)) version++;\n    var data = encodeData(bytes, version);\n    var stream = interleave(data, version);\n\n    var size = version * 4 + 17;\n    var base = createMatrix(size);\n    placeFunctionPatterns(base, version);\n    var reserved = base.map(function (row) {\n      return row.map(function (cell) { return cell !== null; });\n    });\n    placeData(base, reserved, stream);\n\n    var masks = [];\n    for (var mask = 0; mask < 8; mask++) {\n      var candidate = cloneMatrix(base);\n      applyMask(candidate, reserved, mask);\n      placeFormatInfo(candidate, mask);\n      placeVersionInfo(candidate, version);\n      masks.push({\n        penalty: penalty(candidate),\n        rows: candidate.map(function (row) {\n          return row.map(function (b) { return b ? '1' : '0'; }).join('');\n        })\n      });\n    }\n\n    return { version: version, data: data, stream: stream, masks: masks };\n  }\n\n  return {\n    generate: generate,\n    toSvg: toSvg,\n    byteCapacity: byteCapacity,\n    _stages: _stages\n  };\n});\n\n</script>\n<script>\n/* =====================================================================\n   PharmaCheck — application logic\n   Screen routing, camera scanner, prescription code generation,\n   inventory filtering and the reporting dashboard.\n   ===================================================================== */\n(function () {\n  'use strict';\n\n  var $ = function (sel, root) { return (root || document).querySelector(sel); };\n  var $$ = function (sel, root) {\n    return Array.prototype.slice.call((root || document).querySelectorAll(sel));\n  };\n\n  var phone = $('.phone');\n\n  /* ------------------------------------------------------------------ *\n   * Native shell bridge\n   *\n   * No-ops in a plain browser. Inside the Expo WebView it lets the native\n   * side tint the real status bar per screen and route the Android back\n   * button back into this app instead of closing it.\n   * ------------------------------------------------------------------ */\n  var isNative = Boolean(window.__PHARMACHECK_NATIVE__ || window.ReactNativeWebView);\n\n  /* index.html sets this on parse. If the flag only arrived afterwards — an\n     injection that lost the race with the document — apply it here too, so the\n     simulated status bar can never end up stacked under the real one. */\n  if (isNative) document.documentElement.classList.add('is-native');\n\n  function postToNative(message) {\n    if (!isNative) return;\n    try {\n      window.ReactNativeWebView.postMessage(JSON.stringify(message));\n    } catch (e) { /* bridge unavailable */ }\n  }\n\n  /* ------------------------------------------------------------------ *\n   * Toast\n   * ------------------------------------------------------------------ */\n  var toastEl = $('#toast');\n  var toastTimer;\n  function toast(message) {\n    toastEl.textContent = message;\n    toastEl.classList.add('is-on');\n    clearTimeout(toastTimer);\n    toastTimer = setTimeout(hideToast, 2600);\n  }\n\n  /* Sheets slide up over the same corner the toast occupies, so anything\n     still showing is dismissed as one opens. */\n  function hideToast() {\n    clearTimeout(toastTimer);\n    toastEl.classList.remove('is-on');\n  }\n\n  /* ------------------------------------------------------------------ *\n   * Status bar clock\n   * ------------------------------------------------------------------ */\n  function tickClock() {\n    var now = new Date();\n    $('#clock').textContent = now.toLocaleTimeString([], {\n      hour: 'numeric',\n      minute: '2-digit'\n    }).replace(/\\s?[AP]M/i, '');\n  }\n  tickClock();\n  setInterval(tickClock, 20000);\n\n  $('#today-label').textContent = new Date().toLocaleDateString([], {\n    weekday: 'long', day: 'numeric', month: 'long'\n  });\n\n  /* ------------------------------------------------------------------ *\n   * Routing\n   * ------------------------------------------------------------------ */\n  var TAB_FOR_SCREEN = {\n    dashboard: 'dashboard',\n    scanner: 'scanner',\n    manual: 'scanner',   // manual entry lives under the Prescriptions tab\n    inventory: 'inventory',\n    reports: 'reports'\n  };\n\n  var current = 'dashboard';\n\n  function go(name) {\n    if (!$('#screen-' + name)) return;\n\n    $$('.screen').forEach(function (s) { s.classList.remove('is-active'); });\n    $('#screen-' + name).classList.add('is-active');\n\n    var owner = TAB_FOR_SCREEN[name];\n    $$('.tab').forEach(function (t) {\n      var on = t.dataset.go === owner;\n      t.classList.toggle('is-on', on);\n      if (on) t.setAttribute('aria-current', 'page');\n      else t.removeAttribute('aria-current');\n    });\n\n    phone.classList.toggle('is-dark', name === 'scanner');\n\n    if (name === 'scanner') startCamera();\n    else stopCamera();\n\n    if (name === 'reports') {\n      renderReports(activePeriod);\n      // The segmented control can only be measured once its screen is shown.\n      requestAnimationFrame(moveSegPill);\n    }\n\n    var screen = $('#screen-' + name);\n    if (screen.classList.contains('screen--scroll')) screen.scrollTop = 0;\n\n    current = name;\n    postToNative({ type: 'screen', name: name, dark: name === 'scanner' });\n  }\n\n  /* Android hardware back. Closes whatever is open, then walks back to the\n     dashboard; the native side exits the app once we are already there. */\n  window.__pharmacheckBack = function () {\n    if (stockSheet.classList.contains('is-open')) { closeStockSheet(); return; }\n    if (camera.classList.contains('is-locked')) { resetScanner(); return; }\n    if (current === 'manual') { go('scanner'); return; }\n    go('dashboard');\n  };\n\n  document.addEventListener('click', function (event) {\n    var trigger = event.target.closest('[data-go]');\n    if (trigger) {\n      go(trigger.dataset.go);\n      return;\n    }\n    var teller = event.target.closest('[data-toast]');\n    if (teller) toast(teller.dataset.toast);\n  });\n\n  /* ------------------------------------------------------------------ *\n   * Screen 2 — Prescription scanner\n   * ------------------------------------------------------------------ */\n  var camera = $('.camera');\n  var video = $('#camera-feed');\n  var sheet = $('#scan-sheet');\n  var stream = null;\n  var facing = 'environment';\n  var flashOn = false;\n\n  var DEMO_SCAN = {\n    code: 'PC-2026-0481',\n    patient: 'Maria Gonzalez',\n    medication: 'Amoxicillin 500mg',\n    dosage: '1 capsule, 3× daily',\n    quantity: '21 capsules',\n    units: 21,\n    prescriber: 'Dr. E. Okafor'\n  };\n\n  // The QR code shown on the simulated prescription is genuinely encoded.\n  $('#mock-qr').innerHTML = window.QRCodeGen.toSvg(\n    ['PC1', DEMO_SCAN.code, DEMO_SCAN.patient, DEMO_SCAN.medication,\n     DEMO_SCAN.dosage, DEMO_SCAN.quantity].join('|'),\n    { quietZone: 1, dark: '#151A22' }\n  );\n\n  function startCamera() {\n    if (stream || !navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) return;\n    navigator.mediaDevices.getUserMedia({\n      video: { facingMode: facing },\n      audio: false\n    }).then(function (media) {\n      stream = media;\n      video.srcObject = media;\n      camera.classList.add('is-live');\n      $('#camera-source').textContent = 'Live camera';\n    }).catch(function () {\n      /* No camera, or permission denied — the simulated feed stays up. */\n      camera.classList.remove('is-live');\n      $('#camera-source').textContent = 'Simulated feed';\n    });\n  }\n\n  function stopCamera() {\n    if (!stream) return;\n    stream.getTracks().forEach(function (track) { track.stop(); });\n    stream = null;\n    video.srcObject = null;\n    camera.classList.remove('is-live');\n    setFlash(false);\n  }\n\n  function setFlash(on) {\n    flashOn = on;\n    camera.classList.toggle('is-flash', on);\n    var button = $('#flash-toggle');\n    button.setAttribute('aria-pressed', String(on));\n    $('#flash-icon').innerHTML =\n      '<use href=\"' + (on ? '#i-flash' : '#i-flash-off') + '\"/>';\n\n    // Drive the real torch when the device exposes one.\n    if (stream) {\n      var track = stream.getVideoTracks()[0];\n      var caps = track && track.getCapabilities ? track.getCapabilities() : null;\n      if (caps && caps.torch) {\n        track.applyConstraints({ advanced: [{ torch: on }] }).catch(function () {});\n      }\n    }\n  }\n\n  $('#flash-toggle').addEventListener('click', function () {\n    setFlash(!flashOn);\n    toast(flashOn ? 'Flash on' : 'Flash off');\n  });\n\n  $('#camera-flip').addEventListener('click', function () {\n    facing = facing === 'environment' ? 'user' : 'environment';\n    stopCamera();\n    startCamera();\n    toast(facing === 'environment' ? 'Rear camera' : 'Front camera');\n  });\n\n  function openScanResult() {\n    hideToast();\n    camera.classList.add('is-locked');\n    $('#camera-hint').textContent = 'Prescription code recognised';\n    $('#scan-code').textContent = DEMO_SCAN.code;\n    setTimeout(function () {\n      sheet.classList.add('is-open');\n      sheet.setAttribute('aria-hidden', 'false');\n    }, 620);\n  }\n\n  function resetScanner() {\n    sheet.classList.remove('is-open');\n    sheet.setAttribute('aria-hidden', 'true');\n    camera.classList.remove('is-locked');\n    $('#camera-hint').textContent = 'Align QR Code within the frame';\n  }\n\n  $('#shutter').addEventListener('click', function () {\n    if (camera.classList.contains('is-locked')) return;\n    if (navigator.vibrate) navigator.vibrate(18);\n    openScanResult();\n  });\n\n  $('#scan-dismiss').addEventListener('click', resetScanner);\n\n  $('#scan-fill').addEventListener('click', function () {\n    resetScanner();\n    if (!dispense(DEMO_SCAN.medication, DEMO_SCAN.units)) return;\n    toast('Prescription ' + DEMO_SCAN.code + ' filled for ' + DEMO_SCAN.patient);\n    go('dashboard');\n  });\n\n  /* ------------------------------------------------------------------ *\n   * Screen 3 — Manual entry & code generator\n   * ------------------------------------------------------------------ */\n  var form = $('#rx-form');\n  var lastRx = null;\n\n  function setFieldError(name, message) {\n    var input = form.elements[name];\n    var field = input.closest('.field');\n    var slot = $('[data-error-for=\"' + name + '\"]', field);\n    field.classList.toggle('is-bad', Boolean(message));\n    if (slot) slot.textContent = message || '';\n  }\n\n  form.addEventListener('input', function (event) {\n    if (event.target.name) setFieldError(event.target.name, '');\n  });\n\n  function nextCode() {\n    var seq = Number(localStorage.getItem('pharmacheck.seq') || 480) + 1;\n    try { localStorage.setItem('pharmacheck.seq', String(seq)); } catch (e) { /* private mode */ }\n    return 'PC-' + new Date().getFullYear() + '-' + String(seq).padStart(4, '0');\n  }\n\n  form.addEventListener('submit', function (event) {\n    event.preventDefault();\n\n    var values = {\n      patient: form.elements.patient.value.trim(),\n      medication: form.elements.medication.value.trim(),\n      dosage: form.elements.dosage.value.trim(),\n      quantity: form.elements.quantity.value.trim()\n    };\n\n    var ok = true;\n    if (!values.patient) { setFieldError('patient', 'Patient name is required'); ok = false; }\n    if (!values.medication) { setFieldError('medication', 'Medication name is required'); ok = false; }\n    if (!values.dosage) { setFieldError('dosage', 'Dosage is required'); ok = false; }\n    if (!values.quantity || Number(values.quantity) < 1) {\n      setFieldError('quantity', 'Enter a quantity of 1 or more');\n      ok = false;\n    }\n    if (!ok) {\n      toast('Please complete the highlighted fields');\n      return;\n    }\n\n    var code = nextCode();\n    var payload = ['PC1', code, values.patient, values.medication,\n                   values.dosage, values.quantity].join('|');\n\n    try {\n      $('#qr-canvas').innerHTML = window.QRCodeGen.toSvg(payload, { quietZone: 2 });\n    } catch (err) {\n      toast(err.message);\n      return;\n    }\n\n    lastRx = { code: code, payload: payload, values: values };\n    $('#qr-code-text').textContent = code;\n    $('#qr-meta').textContent =\n      values.medication + ' · ' + values.dosage + ' · ' + values.quantity + ' units\\n' +\n      'Issued for ' + values.patient;\n    $('#qr-result').hidden = false;\n    $('#manual-hint').hidden = true;\n    $('#qr-result').scrollIntoView({ behavior: 'smooth', block: 'end' });\n    toast('Prescription code ' + code + ' generated');\n  });\n\n  $('#qr-print').addEventListener('click', function () {\n    if (!lastRx) return;\n\n    if (navigator.share) {\n      navigator.share({\n        title: 'PharmaCheck prescription ' + lastRx.code,\n        text: lastRx.payload\n      }).catch(function () { printCode(); });\n      return;\n    }\n    printCode();\n  });\n\n  function printCode() {\n    var v = lastRx.values;\n    $('#printsheet').innerHTML =\n      '<h1>PharmaCheck Prescription</h1>' +\n      '<p class=\"ps-sub\">' + escapeHtml(lastRx.code) + '</p>' +\n      window.QRCodeGen.toSvg(lastRx.payload, { quietZone: 2 }) +\n      '<dl>' +\n      row('Patient', v.patient) +\n      row('Medication', v.medication) +\n      row('Dosage', v.dosage) +\n      row('Quantity', v.quantity) +\n      row('Issued', new Date().toLocaleString()) +\n      '</dl>';\n    window.print();\n\n    function row(label, value) {\n      return '<div><dt>' + label + '</dt><dd>' + escapeHtml(value) + '</dd></div>';\n    }\n  }\n\n  function escapeHtml(value) {\n    return String(value).replace(/[&<>\"']/g, function (ch) {\n      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[ch];\n    });\n  }\n\n  /* ------------------------------------------------------------------ *\n   * Screen 4 — Inventory\n   * ------------------------------------------------------------------ */\n  var stock = [\n    { name: 'Amoxicillin 500mg',   form: 'Capsules', qty: 34,  reorder: 40,  batch: 'AMX-2291', expiry: '03/2027' },\n    { name: 'Atorvastatin 20mg',   form: 'Tablets',  qty: 264, reorder: 60,  batch: 'ATV-1180', expiry: '11/2027' },\n    { name: 'Metformin 850mg',     form: 'Tablets',  qty: 412, reorder: 100, batch: 'MET-3320', expiry: '06/2028' },\n    { name: 'Salbutamol Inhaler',  form: 'Inhaler',  qty: 7,   reorder: 25,  batch: 'SAL-0442', expiry: '01/2027' },\n    { name: 'Omeprazole 20mg',     form: 'Capsules', qty: 156, reorder: 50,  batch: 'OMP-7715', expiry: '09/2026' },\n    { name: 'Lisinopril 10mg',     form: 'Tablets',  qty: 92,  reorder: 60,  batch: 'LIS-2043', expiry: '04/2028' },\n    { name: 'Ibuprofen 400mg',     form: 'Tablets',  qty: 31,  reorder: 80,  batch: 'IBU-9931', expiry: '12/2026' },\n    { name: 'Cetirizine 10mg',     form: 'Tablets',  qty: 208, reorder: 45,  batch: 'CET-5507', expiry: '08/2028' },\n    { name: 'Insulin Glargine',    form: 'Pens',     qty: 12,  reorder: 20,  batch: 'INS-8812', expiry: '02/2027' },\n    { name: 'Paracetamol 500mg',   form: 'Tablets',  qty: 640, reorder: 150, batch: 'PAR-1002', expiry: '10/2028' },\n    { name: 'Azithromycin 250mg',  form: 'Tablets',  qty: 44,  reorder: 40,  batch: 'AZI-6634', expiry: '05/2027' },\n    { name: 'Warfarin 5mg',        form: 'Tablets',  qty: 9,   reorder: 30,  batch: 'WAR-4419', expiry: '07/2026' }\n  ];\n\n  var listEl = $('#stock-list');\n  var filter = 'all';\n  var lowStockCount = 0;\n\n  function isLow(item) { return item.qty < item.reorder; }\n\n  function isExpiring(item) {\n    var parts = item.expiry.split('/');\n    var when = new Date(Number(parts[1]), Number(parts[0]) - 1, 1);\n    var months = (when.getFullYear() - new Date().getFullYear()) * 12 +\n                 (when.getMonth() - new Date().getMonth());\n    return months <= 12;\n  }\n\n  function renderStock() {\n    var query = $('#inv-search').value.trim().toLowerCase();\n\n    var rows = stock.filter(function (item) {\n      if (query && item.name.toLowerCase().indexOf(query) === -1) return false;\n      if (filter === 'low') return isLow(item);\n      if (filter === 'expiring') return isExpiring(item);\n      return true;\n    });\n\n    listEl.innerHTML = rows.map(function (item) {\n      var low = isLow(item);\n      return '' +\n        '<li class=\"stockrow ' + (low ? 'stockrow--low' : 'stockrow--ok') + '\">' +\n          '<span class=\"stockrow__dot\" aria-hidden=\"true\"></span>' +\n          '<div class=\"stockrow__body\">' +\n            '<p class=\"stockrow__name\">' + escapeHtml(item.name) + '</p>' +\n            '<p class=\"stockrow__meta\">' +\n              '<span>' + escapeHtml(item.form) + ' · ' + escapeHtml(item.batch) + '</span>' +\n              '<span>Exp ' + escapeHtml(item.expiry) + '</span>' +\n              (low\n                ? '<span class=\"stockrow__warn\">' +\n                    '<svg class=\"icon icon--xs\"><use href=\"#i-alert\"/></svg>Low Stock</span>'\n                : '') +\n            '</p>' +\n          '</div>' +\n          '<div class=\"stockrow__right\">' +\n            '<p class=\"stockrow__qty\">' + item.qty + '</p>' +\n            '<p class=\"stockrow__unit\">' + (low ? 'reorder ' + item.reorder : 'in stock') + '</p>' +\n          '</div>' +\n        '</li>';\n    }).join('');\n\n    $('#stock-empty').hidden = rows.length > 0;\n\n    lowStockCount = stock.filter(isLow).length;\n    var lowCount = lowStockCount;\n    $('#inv-summary').textContent =\n      stock.length + ' medicines · ' + lowCount + ' below reorder level';\n    // Keep the dashboard's low-stock metric in step with the real list.\n    $('#dash-low').textContent = lowCount;\n  }\n\n  $('#inv-search').addEventListener('input', renderStock);\n\n  $$('.chip').forEach(function (chip) {\n    chip.addEventListener('click', function () {\n      $$('.chip').forEach(function (other) {\n        other.classList.toggle('is-on', other === chip);\n        other.setAttribute('aria-selected', String(other === chip));\n      });\n      filter = chip.dataset.filter;\n      renderStock();\n    });\n  });\n\n  /* Filling a prescription draws the units down from stock. A pharmacy\n     cannot dispense what it does not have, so a short shelf blocks the fill\n     rather than silently bottoming out at zero. */\n  function dispense(medication, units) {\n    var item = stock.find(function (entry) { return entry.name === medication; });\n    if (!item) return true;\n    if (item.qty < units) {\n      toast('Only ' + item.qty + ' units of ' + medication + ' in stock — reorder before filling');\n      return false;\n    }\n    item.qty -= units;\n    renderStock();\n    return true;\n  }\n\n  /* Add-stock sheet */\n  var stockSheet = $('#stock-sheet');\n  var scrim = $('#scrim');\n  var stockForm = $('#stock-form');\n\n  function openStockSheet() {\n    hideToast();\n    scrim.hidden = false;\n    requestAnimationFrame(function () { scrim.classList.add('is-on'); });\n    stockSheet.classList.add('is-open');\n    stockSheet.setAttribute('aria-hidden', 'false');\n    setTimeout(function () { $('#s-name').focus(); }, 260);\n  }\n\n  function closeStockSheet() {\n    scrim.classList.remove('is-on');\n    stockSheet.classList.remove('is-open');\n    stockSheet.setAttribute('aria-hidden', 'true');\n    setTimeout(function () { scrim.hidden = true; }, 300);\n    stockForm.reset();\n    $$('.field', stockForm).forEach(function (f) { f.classList.remove('is-bad'); });\n  }\n\n  $('#bell').addEventListener('click', function () {\n    toast(lowStockCount + ' medicines below reorder level · ' +\n          '3 prescriptions awaiting verification');\n  });\n\n  $('#fab-add').addEventListener('click', openStockSheet);\n  $('#stock-cancel').addEventListener('click', closeStockSheet);\n  scrim.addEventListener('click', closeStockSheet);\n\n  stockForm.addEventListener('input', function (event) {\n    var field = event.target.closest('.field');\n    if (field) field.classList.remove('is-bad');\n  });\n\n  stockForm.addEventListener('submit', function (event) {\n    event.preventDefault();\n    var name = stockForm.elements.name.value.trim();\n    var qty = Number(stockForm.elements.qty.value);\n    var ok = true;\n\n    if (!name) {\n      markBad(stockForm.elements.name, 'Medicine name is required');\n      ok = false;\n    }\n    if (!qty || qty < 1) {\n      markBad(stockForm.elements.qty, 'Enter 1 unit or more');\n      ok = false;\n    }\n    if (!ok) return;\n\n    var existing = stock.find(function (item) {\n      return item.name.toLowerCase() === name.toLowerCase();\n    });\n\n    if (existing) {\n      existing.qty += qty;\n      toast(qty + ' units added — ' + existing.name + ' now at ' + existing.qty);\n    } else {\n      stock.unshift({\n        name: name, form: 'Units', qty: qty, reorder: Math.max(10, Math.round(qty / 4)),\n        batch: 'NEW-' + Math.floor(1000 + Math.random() * 9000), expiry: '12/2028'\n      });\n      toast(name + ' added to inventory');\n      refreshSuggestions();\n    }\n\n    closeStockSheet();\n    renderStock();\n  });\n\n  function markBad(input, message) {\n    var field = input.closest('.field');\n    field.classList.add('is-bad');\n    var slot = $('.field__error', field);\n    if (slot) slot.textContent = message;\n  }\n\n  function refreshSuggestions() {\n    $('#med-suggestions').innerHTML = stock.map(function (item) {\n      return '<option value=\"' + escapeHtml(item.name) + '\"></option>';\n    }).join('');\n  }\n\n  /* ------------------------------------------------------------------ *\n   * Screen 5 — Financial reports\n   * ------------------------------------------------------------------ */\n  var REPORTS = {\n    daily: {\n      profit: 1284.40, trend: '+9.2% vs yesterday', range: 'Today, 08:00 – 18:00',\n      revenue: 4280.00, cogs: 2995.60,\n      revenueMeta: '38 transactions', cogsMeta: '70.0% of revenue',\n      chartLabel: 'Last 4 days',\n      bars: [{ label: 'Mon', value: 3610 }, { label: 'Tue', value: 4120 },\n             { label: 'Wed', value: 3880 }, { label: 'Thu', value: 4280 }],\n      items: [\n        { name: 'Atorvastatin 20mg', meta: '$612 revenue', margin: 41 },\n        { name: 'Insulin Glargine', meta: '$540 revenue', margin: 36 },\n        { name: 'Omeprazole 20mg', meta: '$388 revenue', margin: 33 },\n        { name: 'Cetirizine 10mg', meta: '$244 revenue', margin: 29 }\n      ]\n    },\n    weekly: {\n      profit: 8942.75, trend: '+12.4% vs last week', range: 'Mon 11 – Sun 17 August',\n      revenue: 29680.00, cogs: 20737.25,\n      revenueMeta: '264 transactions', cogsMeta: '69.9% of revenue',\n      chartLabel: 'Last 4 weeks',\n      bars: [{ label: 'W1', value: 24100 }, { label: 'W2', value: 26840 },\n             { label: 'W3', value: 25390 }, { label: 'W4', value: 29680 }],\n      items: [\n        { name: 'Atorvastatin 20mg', meta: '$4,180 revenue', margin: 42 },\n        { name: 'Metformin 850mg', meta: '$3,640 revenue', margin: 38 },\n        { name: 'Insulin Glargine', meta: '$3,120 revenue', margin: 35 },\n        { name: 'Omeprazole 20mg', meta: '$2,470 revenue', margin: 31 }\n      ]\n    },\n    monthly: {\n      profit: 37610.20, trend: '+7.8% vs last month', range: '1 – 31 August 2026',\n      revenue: 124840.00, cogs: 87229.80,\n      revenueMeta: '1,142 transactions', cogsMeta: '69.9% of revenue',\n      chartLabel: 'Last 4 months',\n      bars: [{ label: 'May', value: 108400 }, { label: 'Jun', value: 115200 },\n             { label: 'Jul', value: 112750 }, { label: 'Aug', value: 124840 }],\n      items: [\n        { name: 'Atorvastatin 20mg', meta: '$17,900 revenue', margin: 43 },\n        { name: 'Metformin 850mg', meta: '$15,240 revenue', margin: 39 },\n        { name: 'Insulin Glargine', meta: '$13,880 revenue', margin: 36 },\n        { name: 'Salbutamol Inhaler', meta: '$9,410 revenue', margin: 30 }\n      ]\n    }\n  };\n\n  var activePeriod = 'weekly';\n\n  var money = function (value, decimals) {\n    return '$' + value.toLocaleString('en-US', {\n      minimumFractionDigits: decimals === undefined ? 2 : decimals,\n      maximumFractionDigits: decimals === undefined ? 2 : decimals\n    });\n  };\n\n  function renderReports(period) {\n    var data = REPORTS[period];\n    if (!data) return;\n\n    $('#profit-value').textContent = money(data.profit);\n    $('#profit-trend').textContent = data.trend;\n    $('#profit-range').textContent = data.range;\n    $('#revenue-value').textContent = money(data.revenue, 0);\n    $('#revenue-meta').textContent = data.revenueMeta;\n    $('#cogs-value').textContent = money(data.cogs, 0);\n    $('#cogs-meta').textContent = data.cogsMeta;\n    $('.chartcard__hint').textContent = data.chartLabel;\n\n    renderChart(data.bars);\n\n    $('#rank-list').innerHTML = data.items.map(function (item, index) {\n      return '' +\n        '<li class=\"rankrow\">' +\n          '<span class=\"rankrow__no\">' + (index + 1) + '</span>' +\n          '<div class=\"rankrow__body\">' +\n            '<p class=\"rankrow__name\">' + escapeHtml(item.name) + '</p>' +\n            '<p class=\"rankrow__meta\">' + escapeHtml(item.meta) + '</p>' +\n          '</div>' +\n          '<span class=\"rankrow__margin\">' + item.margin + '%</span>' +\n        '</li>';\n    }).join('');\n  }\n\n  function renderChart(bars) {\n    var W = 300, H = 150;\n    var padTop = 18, padBottom = 26;\n    var plot = H - padTop - padBottom;\n    var slot = W / bars.length;\n    var barW = 30;\n    var max = Math.max.apply(null, bars.map(function (b) { return b.value; }));\n    var peak = bars.reduce(function (best, b) { return b.value > best.value ? b : best; });\n\n    var svg = ['<svg viewBox=\"0 0 ' + W + ' ' + H + '\" role=\"img\" aria-label=\"Sales trend\">'];\n\n    [0, 0.5, 1].forEach(function (fraction) {\n      var y = padTop + plot * fraction;\n      svg.push('<line class=\"grid-line\" x1=\"0\" y1=\"' + y + '\" x2=\"' + W + '\" y2=\"' + y + '\"/>');\n    });\n\n    bars.forEach(function (bar, index) {\n      var height = Math.max(4, (bar.value / max) * plot);\n      var x = slot * index + (slot - barW) / 2;\n      var y = padTop + plot - height;\n      var isPeak = bar === peak;\n      var fill = isPeak ? 'url(#barPeak)' : '#C9E0FA';\n\n      svg.push('<rect class=\"bar\" x=\"' + x + '\" y=\"' + y + '\" width=\"' + barW +\n        '\" height=\"' + height + '\" rx=\"8\" fill=\"' + fill + '\"/>');\n      svg.push('<text class=\"bar-value\" x=\"' + (x + barW / 2) + '\" y=\"' + (y - 6) +\n        '\" text-anchor=\"middle\">' +\n        (bar.value >= 1000 ? '$' + (bar.value / 1000).toFixed(1) + 'k' : '$' + bar.value) +\n        '</text>');\n      svg.push('<text class=\"bar-label\" x=\"' + (x + barW / 2) + '\" y=\"' + (H - 6) +\n        '\" text-anchor=\"middle\">' + bar.label + '</text>');\n    });\n\n    svg.push('<defs><linearGradient id=\"barPeak\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">' +\n      '<stop offset=\"0%\" stop-color=\"#4A9BF7\"/><stop offset=\"100%\" stop-color=\"#1360C9\"/>' +\n      '</linearGradient></defs>');\n    svg.push('</svg>');\n\n    $('#chart').innerHTML = svg.join('');\n  }\n\n  var segButtons = $$('.segmented__btn');\n  var segPill = $('#segpill');\n\n  function moveSegPill() {\n    var active = $('.segmented__btn.is-on');\n    if (!active) return;\n    segPill.style.width = active.offsetWidth + 'px';\n    segPill.style.transform = 'translateX(' + active.offsetLeft + 'px)';\n  }\n\n  segButtons.forEach(function (button) {\n    button.addEventListener('click', function () {\n      segButtons.forEach(function (other) {\n        other.classList.toggle('is-on', other === button);\n        other.setAttribute('aria-selected', String(other === button));\n      });\n      activePeriod = button.dataset.period;\n      moveSegPill();\n      renderReports(activePeriod);\n    });\n  });\n\n  /* The pill needs a laid-out segmented control, so position it once the\n   * reports screen has been measured. */\n  window.addEventListener('resize', moveSegPill);\n\n  /* ------------------------------------------------------------------ *\n   * Boot\n   * ------------------------------------------------------------------ */\n  $$('.segmented__btn').forEach(function (b) {\n    b.classList.toggle('is-on', b.dataset.period === activePeriod);\n    b.setAttribute('aria-selected', String(b.dataset.period === activePeriod));\n  });\n\n  refreshSuggestions();\n  renderStock();\n  renderReports(activePeriod);\n  requestAnimationFrame(moveSegPill);\n  go('dashboard');\n})();\n\n</script>\n</body>\n</html>\n";
